window.VQ_CURRICULUM = (window.VQ_CURRICULUM || []).concat([{"id":"a1-set-01","title":"Farm Animals • Pets • Wild Animals","subtitle":"A1 foundation adventure 01","level":"A1","set":1,"emoji":"🦊","color":"#F6A844","words":[{"term":"cow","meaning":"بقرة","example":"The cow says moo.","number":1,"id":"a1:001","level":"A1","lessonId":"a1-set-01"},{"term":"goat","meaning":"ماعز","example":"The goat jumps over a rock.","number":2,"id":"a1:002","level":"A1","lessonId":"a1-set-01"},{"term":"sheep","meaning":"خروف","example":"The sheep has soft wool.","number":3,"id":"a1:003","level":"A1","lessonId":"a1-set-01"},{"term":"horse","meaning":"حصان","example":"The horse runs fast.","number":4,"id":"a1:004","level":"A1","lessonId":"a1-set-01"},{"term":"chicken","meaning":"دجاجة","example":"The chicken has wings.","number":5,"id":"a1:005","level":"A1","lessonId":"a1-set-01"},{"term":"duck","meaning":"بطة","example":"The duck swims in the lake.","number":6,"id":"a1:006","level":"A1","lessonId":"a1-set-01"},{"term":"pig","meaning":"خنزير","example":"The pig plays in the mud.","number":7,"id":"a1:007","level":"A1","lessonId":"a1-set-01"},{"term":"donkey","meaning":"حمار","example":"The donkey carries a basket.","number":8,"id":"a1:008","level":"A1","lessonId":"a1-set-01"},{"term":"hen","meaning":"دجاجة بالغة","example":"The hen lays an egg.","number":9,"id":"a1:009","level":"A1","lessonId":"a1-set-01"},{"term":"rooster","meaning":"ديك","example":"The rooster wakes us up.","number":10,"id":"a1:010","level":"A1","lessonId":"a1-set-01"},{"term":"cat","meaning":"قطة","example":"My cat sleeps in a box.","number":11,"id":"a1:011","level":"A1","lessonId":"a1-set-01"},{"term":"dog","meaning":"كلب","example":"The dog wags its tail.","number":12,"id":"a1:012","level":"A1","lessonId":"a1-set-01"},{"term":"rabbit","meaning":"أرنب","example":"The rabbit eats carrots.","number":13,"id":"a1:013","level":"A1","lessonId":"a1-set-01"},{"term":"hamster","meaning":"هامستر","example":"The hamster runs in a wheel.","number":14,"id":"a1:014","level":"A1","lessonId":"a1-set-01"},{"term":"turtle","meaning":"سلحفاة","example":"The turtle walks slowly.","number":15,"id":"a1:015","level":"A1","lessonId":"a1-set-01"},{"term":"parrot","meaning":"ببغاء","example":"The parrot can say hello.","number":16,"id":"a1:016","level":"A1","lessonId":"a1-set-01"},{"term":"fish","meaning":"سمكة","example":"The fish swims in a bowl.","number":17,"id":"a1:017","level":"A1","lessonId":"a1-set-01"},{"term":"bird","meaning":"طائر","example":"The bird sits on a branch.","number":18,"id":"a1:018","level":"A1","lessonId":"a1-set-01"},{"term":"mouse","meaning":"فأر","example":"A mouse is small.","number":19,"id":"a1:019","level":"A1","lessonId":"a1-set-01"},{"term":"kitten","meaning":"قطة صغيرة","example":"The kitten plays with yarn.","number":20,"id":"a1:020","level":"A1","lessonId":"a1-set-01"},{"term":"lion","meaning":"أسد","example":"The lion roars loudly.","number":21,"id":"a1:021","level":"A1","lessonId":"a1-set-01"},{"term":"tiger","meaning":"نمر","example":"The tiger has black stripes.","number":22,"id":"a1:022","level":"A1","lessonId":"a1-set-01"},{"term":"elephant","meaning":"فيل","example":"The elephant has a long trunk.","number":23,"id":"a1:023","level":"A1","lessonId":"a1-set-01"},{"term":"giraffe","meaning":"زرافة","example":"The giraffe has a long neck.","number":24,"id":"a1:024","level":"A1","lessonId":"a1-set-01"},{"term":"zebra","meaning":"حمار وحشي","example":"The zebra has stripes.","number":25,"id":"a1:025","level":"A1","lessonId":"a1-set-01"}],"story":{"title":"The Great Animal Concert","paragraphs":["At Happy Farm, a cow found a golden bell. A goat jumped onto a box, and a sheep wore a funny hat. A horse pulled a little stage. The chicken and duck brought flowers, while a pig and a donkey carried chairs. A hen laid one egg beside the drum. Then the rooster shouted, 'The concert can begin!'","A cat sang first, but a dog barked too loudly. A rabbit hid behind a curtain. The hamster played a tiny piano, and the turtle tapped its feet. A parrot copied every song. A fish watched from its bowl. A bird flew over the stage, a mouse rang the bell, and a kitten chased the music sheets.","Suddenly, five visitors arrived: a lion, a tiger, an elephant, a giraffe, and a zebra. Everyone stopped. Then the elephant played a trumpet with its trunk. The animals laughed and danced together. It was the best concert the farm had ever seen!"],"questions":["What did the cow find?","Who pulled the stage?","Why did the music stop?","What did the elephant play?"]}},{"id":"a1-set-02","title":"Wild Animals • Plants and Land • Sky and Weather","subtitle":"A1 foundation adventure 02","level":"A1","set":2,"emoji":"🦊","color":"#F6A844","words":[{"term":"monkey","meaning":"قرد","example":"The monkey swings in a tree.","number":26,"id":"a1:026","level":"A1","lessonId":"a1-set-02"},{"term":"bear","meaning":"دب","example":"The bear is very strong.","number":27,"id":"a1:027","level":"A1","lessonId":"a1-set-02"},{"term":"snake","meaning":"ثعبان","example":"The snake moves without legs.","number":28,"id":"a1:028","level":"A1","lessonId":"a1-set-02"},{"term":"frog","meaning":"ضفدع","example":"The frog jumps into water.","number":29,"id":"a1:029","level":"A1","lessonId":"a1-set-02"},{"term":"crocodile","meaning":"تمساح","example":"The crocodile has big teeth.","number":30,"id":"a1:030","level":"A1","lessonId":"a1-set-02"},{"term":"tree","meaning":"شجرة","example":"A tree gives us shade.","number":31,"id":"a1:031","level":"A1","lessonId":"a1-set-02"},{"term":"flower","meaning":"زهرة","example":"This flower smells sweet.","number":32,"id":"a1:032","level":"A1","lessonId":"a1-set-02"},{"term":"grass","meaning":"عشب","example":"The rabbit eats grass.","number":33,"id":"a1:033","level":"A1","lessonId":"a1-set-02"},{"term":"leaf","meaning":"ورقة شجر","example":"A green leaf falls down.","number":34,"id":"a1:034","level":"A1","lessonId":"a1-set-02"},{"term":"seed","meaning":"بذرة","example":"A tiny seed grows into a plant.","number":35,"id":"a1:035","level":"A1","lessonId":"a1-set-02"},{"term":"plant","meaning":"نبتة","example":"Water the plant every day.","number":36,"id":"a1:036","level":"A1","lessonId":"a1-set-02"},{"term":"rock","meaning":"صخرة","example":"Leo sits on a rock.","number":37,"id":"a1:037","level":"A1","lessonId":"a1-set-02"},{"term":"mountain","meaning":"جبل","example":"A mountain is very high.","number":38,"id":"a1:038","level":"A1","lessonId":"a1-set-02"},{"term":"river","meaning":"نهر","example":"The river flows past the village.","number":39,"id":"a1:039","level":"A1","lessonId":"a1-set-02"},{"term":"lake","meaning":"بحيرة","example":"Ducks swim in the lake.","number":40,"id":"a1:040","level":"A1","lessonId":"a1-set-02"},{"term":"sun","meaning":"شمس","example":"The sun shines in the sky.","number":41,"id":"a1:041","level":"A1","lessonId":"a1-set-02"},{"term":"moon","meaning":"قمر","example":"The moon shines at night.","number":42,"id":"a1:042","level":"A1","lessonId":"a1-set-02"},{"term":"star","meaning":"نجمة","example":"A bright star is in the sky.","number":43,"id":"a1:043","level":"A1","lessonId":"a1-set-02"},{"term":"sky","meaning":"سماء","example":"The sky is blue today.","number":44,"id":"a1:044","level":"A1","lessonId":"a1-set-02"},{"term":"cloud","meaning":"سحابة","example":"A cloud hides the sun.","number":45,"id":"a1:045","level":"A1","lessonId":"a1-set-02"},{"term":"rain","meaning":"مطر","example":"The rain makes the grass wet.","number":46,"id":"a1:046","level":"A1","lessonId":"a1-set-02"},{"term":"snow","meaning":"ثلج","example":"The snow is cold and white.","number":47,"id":"a1:047","level":"A1","lessonId":"a1-set-02"},{"term":"wind","meaning":"رياح","example":"The wind moves the leaves.","number":48,"id":"a1:048","level":"A1","lessonId":"a1-set-02"},{"term":"storm","meaning":"عاصفة","example":"We stay inside during a storm.","number":49,"id":"a1:049","level":"A1","lessonId":"a1-set-02"},{"term":"rainbow","meaning":"قوس قزح","example":"A rainbow has many colors.","number":50,"id":"a1:050","level":"A1","lessonId":"a1-set-02"}],"story":{"title":"The Rainbow Rescue","paragraphs":["One morning a monkey woke up in a tall tree. A bear was sleeping below, a snake was hiding under a rock, and a frog was sitting by a lake. Far away, a crocodile rested beside a river. A bright flower grew in the grass. The monkey found a leaf and a seed, so he decided to plant a little garden.","He put the seed into the ground near a green plant. Then he looked past the mountain. The sun disappeared behind a cloud, and the sky turned gray. Even the moon and one tiny star seemed to hide. Soon rain began to fall. Cold wind shook the branches, and a strong storm covered the hill. 'Will my seed be safe?' cried the monkey. Snow even fell on the mountain top.","The bear covered the new garden with a wide leaf. The frog carried water away, and the crocodile made a little wall of stones. At last the storm ended. A beautiful rainbow appeared over the river. 'Look!' shouted the monkey. 'The sun has come back, and my seed can grow!'"],"questions":["What did the monkey plant?","Where was the frog sitting?","How did the friends protect the garden?","What appeared after the storm?"]}},{"id":"a1-set-03","title":"Colors • Numbers 1-10 • Numbers 11-20","subtitle":"A1 foundation adventure 03","level":"A1","set":3,"emoji":"🦊","color":"#F6A844","words":[{"term":"red","meaning":"أحمر","example":"I have a red pencil.","number":51,"id":"a1:051","level":"A1","lessonId":"a1-set-03"},{"term":"blue","meaning":"أزرق","example":"I have a blue pencil.","number":52,"id":"a1:052","level":"A1","lessonId":"a1-set-03"},{"term":"yellow","meaning":"أصفر","example":"I have a yellow pencil.","number":53,"id":"a1:053","level":"A1","lessonId":"a1-set-03"},{"term":"green","meaning":"أخضر","example":"I have a green pencil.","number":54,"id":"a1:054","level":"A1","lessonId":"a1-set-03"},{"term":"orange","meaning":"برتقالي","example":"I have a orange pencil.","number":55,"id":"a1:055","level":"A1","lessonId":"a1-set-03"},{"term":"purple","meaning":"بنفسجي","example":"I have a purple pencil.","number":56,"id":"a1:056","level":"A1","lessonId":"a1-set-03"},{"term":"pink","meaning":"وردي","example":"I have a pink pencil.","number":57,"id":"a1:057","level":"A1","lessonId":"a1-set-03"},{"term":"black","meaning":"أسود","example":"I have a black pencil.","number":58,"id":"a1:058","level":"A1","lessonId":"a1-set-03"},{"term":"white","meaning":"أبيض","example":"I have a white pencil.","number":59,"id":"a1:059","level":"A1","lessonId":"a1-set-03"},{"term":"brown","meaning":"بني","example":"I have a brown pencil.","number":60,"id":"a1:060","level":"A1","lessonId":"a1-set-03"},{"term":"one","meaning":"واحد","example":"I can count to one.","number":61,"id":"a1:061","level":"A1","lessonId":"a1-set-03"},{"term":"two","meaning":"اثنان","example":"I can count to two.","number":62,"id":"a1:062","level":"A1","lessonId":"a1-set-03"},{"term":"three","meaning":"ثلاثة","example":"I can count to three.","number":63,"id":"a1:063","level":"A1","lessonId":"a1-set-03"},{"term":"four","meaning":"أربعة","example":"I can count to four.","number":64,"id":"a1:064","level":"A1","lessonId":"a1-set-03"},{"term":"five","meaning":"خمسة","example":"I can count to five.","number":65,"id":"a1:065","level":"A1","lessonId":"a1-set-03"},{"term":"six","meaning":"ستة","example":"I can count to six.","number":66,"id":"a1:066","level":"A1","lessonId":"a1-set-03"},{"term":"seven","meaning":"سبعة","example":"I can count to seven.","number":67,"id":"a1:067","level":"A1","lessonId":"a1-set-03"},{"term":"eight","meaning":"ثمانية","example":"I can count to eight.","number":68,"id":"a1:068","level":"A1","lessonId":"a1-set-03"},{"term":"nine","meaning":"تسعة","example":"I can count to nine.","number":69,"id":"a1:069","level":"A1","lessonId":"a1-set-03"},{"term":"ten","meaning":"عشرة","example":"I can count to ten.","number":70,"id":"a1:070","level":"A1","lessonId":"a1-set-03"},{"term":"eleven","meaning":"أحد عشر","example":"I can count to eleven.","number":71,"id":"a1:071","level":"A1","lessonId":"a1-set-03"},{"term":"twelve","meaning":"اثنا عشر","example":"I can count to twelve.","number":72,"id":"a1:072","level":"A1","lessonId":"a1-set-03"},{"term":"thirteen","meaning":"ثلاثة عشر","example":"I can count to thirteen.","number":73,"id":"a1:073","level":"A1","lessonId":"a1-set-03"},{"term":"fourteen","meaning":"أربعة عشر","example":"I can count to fourteen.","number":74,"id":"a1:074","level":"A1","lessonId":"a1-set-03"},{"term":"fifteen","meaning":"خمسة عشر","example":"I can count to fifteen.","number":75,"id":"a1:075","level":"A1","lessonId":"a1-set-03"}],"story":{"title":"The Fifteen Surprise Boxes","paragraphs":["Mia and Leo planned a color party. On the table were red, blue, yellow, green, orange, purple, pink, black, white, and brown ribbons. 'Which one is the prettiest?' asked Leo. 'All of them!' said Mia. They had a very special game with fifteen surprise boxes.","On box one, Mia drew a star. Box two had a cat, and box three had a smiling sun. Box four held a little bell. They put five feathers in box five and six shells in box six. 'Seven is my lucky number,' said Leo, so he drew seven hearts. Box eight got eight dots. Box nine had nine tiny fish, and box ten had ten bright flowers.","The children counted again. 'Eleven, twelve, thirteen, fourteen ... and fifteen!' shouted Mia as she opened the last box. Inside was a rainbow cake. Leo laughed. 'We used every color, and now we can eat our surprise!'"],"questions":["What did Mia and Leo plan?","How many surprise boxes did they have?","What was in the last box?","Which box had ten flowers?"]}},{"id":"a1-set-04","title":"Numbers 11-20 • My Family • People Around Us","subtitle":"A1 foundation adventure 04","level":"A1","set":4,"emoji":"🦊","color":"#F6A844","words":[{"term":"sixteen","meaning":"ستة عشر","example":"I can count to sixteen.","number":76,"id":"a1:076","level":"A1","lessonId":"a1-set-04"},{"term":"seventeen","meaning":"سبعة عشر","example":"I can count to seventeen.","number":77,"id":"a1:077","level":"A1","lessonId":"a1-set-04"},{"term":"eighteen","meaning":"ثمانية عشر","example":"I can count to eighteen.","number":78,"id":"a1:078","level":"A1","lessonId":"a1-set-04"},{"term":"nineteen","meaning":"تسعة عشر","example":"I can count to nineteen.","number":79,"id":"a1:079","level":"A1","lessonId":"a1-set-04"},{"term":"twenty","meaning":"عشرون","example":"I can count to twenty.","number":80,"id":"a1:080","level":"A1","lessonId":"a1-set-04"},{"term":"mother","meaning":"أم","example":"My mother reads with me every evening.","number":81,"id":"a1:081","level":"A1","lessonId":"a1-set-04"},{"term":"father","meaning":"أب","example":"My father makes breakfast on Friday.","number":82,"id":"a1:082","level":"A1","lessonId":"a1-set-04"},{"term":"brother","meaning":"أخ","example":"My brother can ride a bicycle.","number":83,"id":"a1:083","level":"A1","lessonId":"a1-set-04"},{"term":"sister","meaning":"أخت","example":"My sister draws funny animals.","number":84,"id":"a1:084","level":"A1","lessonId":"a1-set-04"},{"term":"baby","meaning":"رضيع","example":"The baby laughs at the toy.","number":85,"id":"a1:085","level":"A1","lessonId":"a1-set-04"},{"term":"grandmother","meaning":"جدة","example":"My grandmother tells exciting stories.","number":86,"id":"a1:086","level":"A1","lessonId":"a1-set-04"},{"term":"grandfather","meaning":"جد","example":"My grandfather has a beautiful garden.","number":87,"id":"a1:087","level":"A1","lessonId":"a1-set-04"},{"term":"aunt","meaning":"عمة أو خالة","example":"My aunt visits us on Saturday.","number":88,"id":"a1:088","level":"A1","lessonId":"a1-set-04"},{"term":"uncle","meaning":"عم أو خال","example":"My uncle drives a big truck.","number":89,"id":"a1:089","level":"A1","lessonId":"a1-set-04"},{"term":"cousin","meaning":"ابن أو ابنة العم أو الخال","example":"My cousin and I play together.","number":90,"id":"a1:090","level":"A1","lessonId":"a1-set-04"},{"term":"boy","meaning":"ولد","example":"The boy carries a heavy school bag.","number":91,"id":"a1:091","level":"A1","lessonId":"a1-set-04"},{"term":"girl","meaning":"بنت","example":"The girl shares her colorful pencils.","number":92,"id":"a1:092","level":"A1","lessonId":"a1-set-04"},{"term":"man","meaning":"رجل","example":"The man waits at the bus stop.","number":93,"id":"a1:093","level":"A1","lessonId":"a1-set-04"},{"term":"woman","meaning":"امرأة","example":"The woman buys fresh fruit.","number":94,"id":"a1:094","level":"A1","lessonId":"a1-set-04"},{"term":"child","meaning":"طفل","example":"Every child has a name.","number":95,"id":"a1:095","level":"A1","lessonId":"a1-set-04"},{"term":"friend","meaning":"صديق","example":"My friend helps me spell words.","number":96,"id":"a1:096","level":"A1","lessonId":"a1-set-04"},{"term":"teacher","meaning":"معلم","example":"The teacher writes on the board.","number":97,"id":"a1:097","level":"A1","lessonId":"a1-set-04"},{"term":"student","meaning":"طالب","example":"The student answers a question.","number":98,"id":"a1:098","level":"A1","lessonId":"a1-set-04"},{"term":"classmate","meaning":"زميل صف","example":"My classmate lends me an eraser.","number":99,"id":"a1:099","level":"A1","lessonId":"a1-set-04"},{"term":"family","meaning":"عائلة","example":"Our family eats dinner together.","number":100,"id":"a1:100","level":"A1","lessonId":"a1-set-04"}],"story":{"title":"Grandma’s Big Birthday Puzzle","paragraphs":["It was grandmother's birthday. A boy named Sam and a girl named Lily made a puzzle for their family. There were five big cards with the numbers sixteen, seventeen, eighteen, nineteen, and twenty. 'We must find twenty little stars before the guests arrive!' said Sam.","Their mother made a cake, and their father put up lights. Their brother and sister helped the baby clap. Grandfather hid a star beside the window. An aunt put another in a shoe, an uncle put one under a chair, and a cousin put one behind a book. Every child looked carefully.","A friendly man came to bring balloons. A woman from the next house brought flowers. Their friend brought a funny hat. The teacher from Sam's school arrived with a student and a classmate. 'We have found all the stars!' shouted Lily. At last, the whole family sang. Grandmother smiled and said, 'This is better than any present.'"],"questions":["What were the children looking for?","Who hid a star beside the window?","What did the man bring?","How did grandmother feel?"]}},{"id":"a1-set-05","title":"My Face • My Body • Clothes","subtitle":"A1 foundation adventure 05","level":"A1","set":5,"emoji":"🦊","color":"#F6A844","words":[{"term":"face","meaning":"وجه","example":"Wash your face before school.","number":101,"id":"a1:101","level":"A1","lessonId":"a1-set-05"},{"term":"head","meaning":"رأس","example":"Wear a helmet to protect your head.","number":102,"id":"a1:102","level":"A1","lessonId":"a1-set-05"},{"term":"hair","meaning":"شعر","example":"Her hair is long.","number":103,"id":"a1:103","level":"A1","lessonId":"a1-set-05"},{"term":"eye","meaning":"عين","example":"I close one eye and smile.","number":104,"id":"a1:104","level":"A1","lessonId":"a1-set-05"},{"term":"ear","meaning":"أذن","example":"I hear music with my ear.","number":105,"id":"a1:105","level":"A1","lessonId":"a1-set-05"},{"term":"nose","meaning":"أنف","example":"The clown has a funny red nose.","number":106,"id":"a1:106","level":"A1","lessonId":"a1-set-05"},{"term":"mouth","meaning":"فم","example":"Open your mouth to say ah.","number":107,"id":"a1:107","level":"A1","lessonId":"a1-set-05"},{"term":"tooth","meaning":"سن","example":"My tooth is clean.","number":108,"id":"a1:108","level":"A1","lessonId":"a1-set-05"},{"term":"cheek","meaning":"خد","example":"The baby has a rosy cheek.","number":109,"id":"a1:109","level":"A1","lessonId":"a1-set-05"},{"term":"chin","meaning":"ذقن","example":"The boy rests his chin on his hand.","number":110,"id":"a1:110","level":"A1","lessonId":"a1-set-05"},{"term":"arm","meaning":"ذراع","example":"I lift my arm to answer.","number":111,"id":"a1:111","level":"A1","lessonId":"a1-set-05"},{"term":"hand","meaning":"يد","example":"Please raise your hand.","number":112,"id":"a1:112","level":"A1","lessonId":"a1-set-05"},{"term":"finger","meaning":"إصبع","example":"Point with one finger.","number":113,"id":"a1:113","level":"A1","lessonId":"a1-set-05"},{"term":"thumb","meaning":"إبهام","example":"Give me a thumbs-up with your thumb.","number":114,"id":"a1:114","level":"A1","lessonId":"a1-set-05"},{"term":"leg","meaning":"ساق","example":"A horse has a strong leg.","number":115,"id":"a1:115","level":"A1","lessonId":"a1-set-05"},{"term":"foot","meaning":"قدم","example":"My left foot is in the water.","number":116,"id":"a1:116","level":"A1","lessonId":"a1-set-05"},{"term":"knee","meaning":"ركبة","example":"I bend my knee when I jump.","number":117,"id":"a1:117","level":"A1","lessonId":"a1-set-05"},{"term":"toe","meaning":"إصبع قدم","example":"I can touch my toe.","number":118,"id":"a1:118","level":"A1","lessonId":"a1-set-05"},{"term":"back","meaning":"ظهر","example":"Carry your backpack on your back.","number":119,"id":"a1:119","level":"A1","lessonId":"a1-set-05"},{"term":"stomach","meaning":"بطن","example":"My stomach is full after lunch.","number":120,"id":"a1:120","level":"A1","lessonId":"a1-set-05"},{"term":"shirt","meaning":"قميص","example":"My white shirt is clean today.","number":121,"id":"a1:121","level":"A1","lessonId":"a1-set-05"},{"term":"trousers","meaning":"بنطال","example":"These trousers are blue.","number":122,"id":"a1:122","level":"A1","lessonId":"a1-set-05"},{"term":"dress","meaning":"فستان","example":"Sara wears a dress to the party.","number":123,"id":"a1:123","level":"A1","lessonId":"a1-set-05"},{"term":"skirt","meaning":"تنورة","example":"The skirt has tiny flowers.","number":124,"id":"a1:124","level":"A1","lessonId":"a1-set-05"},{"term":"socks","meaning":"جوارب","example":"My socks are white.","number":125,"id":"a1:125","level":"A1","lessonId":"a1-set-05"}],"story":{"title":"The Robot Who Dressed Backwards","paragraphs":["Leo built a small robot with a round face and a square head. It had blue hair, one big eye, one tiny ear, a red nose, and a smiling mouth. Leo drew a white tooth, a pink cheek, and a pointed chin. 'You look wonderful!' he said.","Then the robot tried to get dressed. First it put a shirt on its leg. Next it pulled trousers over its head! It wore a dress on one arm and a skirt over its foot. Two socks covered its hands and one toe. One finger poked through a hole, but its thumb got stuck. When the robot bent its knee, it fell onto its back and bumped its stomach.","'Oh dear,' laughed Leo. He pointed to each body part: 'This is your hand, this is your foot, and these are your clothes.' The robot blinked and tried again. At last it stood up correctly. 'Now I look ready for school!' it said proudly."],"questions":["What did Leo build?","Where did the robot first put its shirt?","Why did the robot fall?","Who helped the robot?"]}},{"id":"a1-set-06","title":"Clothes • More Clothes • Fruit","subtitle":"A1 foundation adventure 06","level":"A1","set":6,"emoji":"🦊","color":"#F6A844","words":[{"term":"shoes","meaning":"أحذية","example":"These shoes are new.","number":126,"id":"a1:126","level":"A1","lessonId":"a1-set-06"},{"term":"hat","meaning":"قبعة","example":"My hat keeps the sun away.","number":127,"id":"a1:127","level":"A1","lessonId":"a1-set-06"},{"term":"coat","meaning":"معطف","example":"I wear a coat in cold weather.","number":128,"id":"a1:128","level":"A1","lessonId":"a1-set-06"},{"term":"jacket","meaning":"سترة","example":"Leo zips up his jacket.","number":129,"id":"a1:129","level":"A1","lessonId":"a1-set-06"},{"term":"scarf","meaning":"وشاح","example":"A red scarf keeps my neck warm.","number":130,"id":"a1:130","level":"A1","lessonId":"a1-set-06"},{"term":"T-shirt","meaning":"قميص قصير الأكمام","example":"My T-shirt has a funny cat on it.","number":131,"id":"a1:131","level":"A1","lessonId":"a1-set-06"},{"term":"shorts","meaning":"شورت","example":"My shorts are red.","number":132,"id":"a1:132","level":"A1","lessonId":"a1-set-06"},{"term":"sweater","meaning":"كنزة","example":"This sweater is made of wool.","number":133,"id":"a1:133","level":"A1","lessonId":"a1-set-06"},{"term":"jeans","meaning":"جينز","example":"These jeans are blue.","number":134,"id":"a1:134","level":"A1","lessonId":"a1-set-06"},{"term":"boots","meaning":"أحذية طويلة","example":"My boots are big.","number":135,"id":"a1:135","level":"A1","lessonId":"a1-set-06"},{"term":"gloves","meaning":"قفازات","example":"These gloves are warm.","number":136,"id":"a1:136","level":"A1","lessonId":"a1-set-06"},{"term":"cap","meaning":"قبعة بواق","example":"He puts on a cap before playing.","number":137,"id":"a1:137","level":"A1","lessonId":"a1-set-06"},{"term":"belt","meaning":"حزام","example":"My belt holds up my trousers.","number":138,"id":"a1:138","level":"A1","lessonId":"a1-set-06"},{"term":"uniform","meaning":"زي موحد","example":"We wear our school uniform on weekdays.","number":139,"id":"a1:139","level":"A1","lessonId":"a1-set-06"},{"term":"pocket","meaning":"جيب","example":"I keep a small coin in my pocket.","number":140,"id":"a1:140","level":"A1","lessonId":"a1-set-06"},{"term":"apple","meaning":"تفاحة","example":"I eat a crunchy apple at break time.","number":141,"id":"a1:141","level":"A1","lessonId":"a1-set-06"},{"term":"banana","meaning":"موزة","example":"A monkey is eating a banana.","number":142,"id":"a1:142","level":"A1","lessonId":"a1-set-06"},{"term":"pear","meaning":"كمثرى","example":"The yellow pear tastes sweet.","number":143,"id":"a1:143","level":"A1","lessonId":"a1-set-06"},{"term":"grape","meaning":"حبة عنب","example":"I put one grape on my plate.","number":144,"id":"a1:144","level":"A1","lessonId":"a1-set-06"},{"term":"mango","meaning":"مانجو","example":"A ripe mango smells delicious.","number":145,"id":"a1:145","level":"A1","lessonId":"a1-set-06"},{"term":"peach","meaning":"خوخة","example":"This peach has soft skin.","number":146,"id":"a1:146","level":"A1","lessonId":"a1-set-06"},{"term":"strawberry","meaning":"فراولة","example":"The strawberry is red and sweet.","number":147,"id":"a1:147","level":"A1","lessonId":"a1-set-06"},{"term":"watermelon","meaning":"بطيخ","example":"This watermelon is huge.","number":148,"id":"a1:148","level":"A1","lessonId":"a1-set-06"},{"term":"lemon","meaning":"ليمونة","example":"The lemon tastes very sour.","number":149,"id":"a1:149","level":"A1","lessonId":"a1-set-06"},{"term":"cherry","meaning":"كرزة","example":"A cherry grows on a tree.","number":150,"id":"a1:150","level":"A1","lessonId":"a1-set-06"}],"story":{"title":"The Picnic with Too Many Pockets","paragraphs":["It was picnic day, but the weather kept changing. Nina put on her shoes and a hat. Her brother wore a coat, a jacket, and a scarf. 'You are dressed for winter!' she laughed. He took off the jacket and put on a T-shirt and shorts. Then a cool wind came, so he changed into a sweater and jeans. Nina packed boots, gloves, and a cap, just in case.","At school, their teacher checked everyone's uniform. Nina fastened her belt and put a tiny map in her pocket. The class walked to a sunny field with a basket of fruit. Inside were an apple, a banana, a pear, a grape, a mango, a peach, a strawberry, a slice of watermelon, a lemon, and a cherry.","Suddenly a gust of wind blew Nina's map away! Her brother pulled it from the top of his hat. 'Your silly hat saved our picnic!' she said. They shared the fruit and laughed together."],"questions":["Why did the brother keep changing clothes?","What did Nina put in her pocket?","What blew away?","Where did the brother find it?"]}},{"id":"a1-set-07","title":"Vegetables • Everyday Foods • Drinks","subtitle":"A1 foundation adventure 07","level":"A1","set":7,"emoji":"🦊","color":"#F6A844","words":[{"term":"carrot","meaning":"جزرة","example":"The rabbit munches a carrot.","number":151,"id":"a1:151","level":"A1","lessonId":"a1-set-07"},{"term":"potato","meaning":"بطاطس","example":"We bake a potato for lunch.","number":152,"id":"a1:152","level":"A1","lessonId":"a1-set-07"},{"term":"tomato","meaning":"طماطم","example":"I cut a tomato for my sandwich.","number":153,"id":"a1:153","level":"A1","lessonId":"a1-set-07"},{"term":"onion","meaning":"بصلة","example":"The onion makes my eyes water.","number":154,"id":"a1:154","level":"A1","lessonId":"a1-set-07"},{"term":"cucumber","meaning":"خيار","example":"The cucumber is long and green.","number":155,"id":"a1:155","level":"A1","lessonId":"a1-set-07"},{"term":"lettuce","meaning":"خس","example":"The rabbit eats lettuce.","number":156,"id":"a1:156","level":"A1","lessonId":"a1-set-07"},{"term":"cabbage","meaning":"ملفوف","example":"A cabbage has many leaves.","number":157,"id":"a1:157","level":"A1","lessonId":"a1-set-07"},{"term":"pepper","meaning":"فلفل","example":"The red pepper tastes sweet.","number":158,"id":"a1:158","level":"A1","lessonId":"a1-set-07"},{"term":"corn","meaning":"ذرة","example":"The corn is yellow.","number":159,"id":"a1:159","level":"A1","lessonId":"a1-set-07"},{"term":"broccoli","meaning":"بروكلي","example":"We eat broccoli.","number":160,"id":"a1:160","level":"A1","lessonId":"a1-set-07"},{"term":"bread","meaning":"خبز","example":"The bread is fresh.","number":161,"id":"a1:161","level":"A1","lessonId":"a1-set-07"},{"term":"rice","meaning":"أرز","example":"I eat rice for lunch.","number":162,"id":"a1:162","level":"A1","lessonId":"a1-set-07"},{"term":"egg","meaning":"بيضة","example":"A hen lays an egg.","number":163,"id":"a1:163","level":"A1","lessonId":"a1-set-07"},{"term":"cheese","meaning":"جبن","example":"I like cheese.","number":164,"id":"a1:164","level":"A1","lessonId":"a1-set-07"},{"term":"milk","meaning":"حليب","example":"I drink milk every day.","number":165,"id":"a1:165","level":"A1","lessonId":"a1-set-07"},{"term":"butter","meaning":"زبدة","example":"Put butter on bread.","number":166,"id":"a1:166","level":"A1","lessonId":"a1-set-07"},{"term":"soup","meaning":"حساء","example":"The soup is hot.","number":167,"id":"a1:167","level":"A1","lessonId":"a1-set-07"},{"term":"meat","meaning":"لحم","example":"We cook meat.","number":168,"id":"a1:168","level":"A1","lessonId":"a1-set-07"},{"term":"sandwich","meaning":"شطيرة","example":"I made a cheese sandwich.","number":169,"id":"a1:169","level":"A1","lessonId":"a1-set-07"},{"term":"cereal","meaning":"حبوب الإفطار","example":"I eat cereal for breakfast.","number":170,"id":"a1:170","level":"A1","lessonId":"a1-set-07"},{"term":"water","meaning":"ماء","example":"Please drink water.","number":171,"id":"a1:171","level":"A1","lessonId":"a1-set-07"},{"term":"juice","meaning":"عصير","example":"I drink orange juice after playing.","number":172,"id":"a1:172","level":"A1","lessonId":"a1-set-07"},{"term":"tea","meaning":"شاي","example":"My grandfather enjoys mint tea.","number":173,"id":"a1:173","level":"A1","lessonId":"a1-set-07"},{"term":"coffee","meaning":"قهوة","example":"My father drinks coffee in the morning.","number":174,"id":"a1:174","level":"A1","lessonId":"a1-set-07"},{"term":"lemonade","meaning":"شراب الليمون","example":"Cold lemonade tastes good in summer.","number":175,"id":"a1:175","level":"A1","lessonId":"a1-set-07"}],"story":{"title":"The Soup That Saved Lunch","paragraphs":["Chef Ben wanted to make lunch for his friends. He found a carrot, a potato, a tomato, an onion, and a cucumber. He washed the lettuce and cabbage, then chopped a pepper. He added corn and broccoli to a big pot. 'A rainbow of vegetables!' he said.","On another table he placed bread, rice, an egg, cheese, and milk. He was going to make a sandwich with butter, meat, and salad. There was also cereal for his little sister. She asked for water, while their mother wanted juice. Grandpa chose tea, Grandma chose coffee, and Aunt May asked for lemonade.","But the sandwich fell onto the floor! 'Oh no!' cried Ben. His sister pointed to the pot. 'What about the soup?' she asked. Ben tasted it. Delicious! Everyone enjoyed warm vegetable soup with bread. Grandpa smiled. 'Sometimes a mistake makes the best lunch.'"],"questions":["What was Ben making first?","What fell onto the floor?","What saved lunch?","What did Grandpa learn?"]}},{"id":"a1-set-08","title":"Drinks • Sweet Treats • In the Kitchen","subtitle":"A1 foundation adventure 08","level":"A1","set":8,"emoji":"🦊","color":"#F6A844","words":[{"term":"milkshake","meaning":"مخفوق الحليب","example":"This milkshake has banana in it.","number":176,"id":"a1:176","level":"A1","lessonId":"a1-set-08"},{"term":"cola","meaning":"كولا","example":"A can of cola contains sugar.","number":177,"id":"a1:177","level":"A1","lessonId":"a1-set-08"},{"term":"smoothie","meaning":"عصير فواكه كثيف","example":"Maha makes a fruit smoothie.","number":178,"id":"a1:178","level":"A1","lessonId":"a1-set-08"},{"term":"cocoa","meaning":"كاكاو","example":"We drink hot cocoa in winter.","number":179,"id":"a1:179","level":"A1","lessonId":"a1-set-08"},{"term":"soda","meaning":"مشروب غازي","example":"Water is healthier than soda.","number":180,"id":"a1:180","level":"A1","lessonId":"a1-set-08"},{"term":"cake","meaning":"كعكة","example":"We share a cake on my birthday.","number":181,"id":"a1:181","level":"A1","lessonId":"a1-set-08"},{"term":"cookie","meaning":"قطعة بسكويت","example":"The cookie smells of chocolate.","number":182,"id":"a1:182","level":"A1","lessonId":"a1-set-08"},{"term":"biscuit","meaning":"بسكويت","example":"I dip a biscuit into milk.","number":183,"id":"a1:183","level":"A1","lessonId":"a1-set-08"},{"term":"chocolate","meaning":"شوكولاتة","example":"I love chocolate.","number":184,"id":"a1:184","level":"A1","lessonId":"a1-set-08"},{"term":"candy","meaning":"حلوى","example":"Too much candy hurts your teeth.","number":185,"id":"a1:185","level":"A1","lessonId":"a1-set-08"},{"term":"ice cream","meaning":"آيس كريم","example":"The ice cream melts in the sun.","number":186,"id":"a1:186","level":"A1","lessonId":"a1-set-08"},{"term":"pudding","meaning":"بودينغ","example":"I eat vanilla pudding with a spoon.","number":187,"id":"a1:187","level":"A1","lessonId":"a1-set-08"},{"term":"honey","meaning":"عسل","example":"Bees make honey.","number":188,"id":"a1:188","level":"A1","lessonId":"a1-set-08"},{"term":"jam","meaning":"مربى","example":"I put jam on toast.","number":189,"id":"a1:189","level":"A1","lessonId":"a1-set-08"},{"term":"sugar","meaning":"سكر","example":"Do not eat too much sugar.","number":190,"id":"a1:190","level":"A1","lessonId":"a1-set-08"},{"term":"fork","meaning":"شوكة","example":"I use a fork to eat salad.","number":191,"id":"a1:191","level":"A1","lessonId":"a1-set-08"},{"term":"spoon","meaning":"ملعقة","example":"A spoon is useful for soup.","number":192,"id":"a1:192","level":"A1","lessonId":"a1-set-08"},{"term":"knife","meaning":"سكين","example":"A grown-up uses the knife carefully.","number":193,"id":"a1:193","level":"A1","lessonId":"a1-set-08"},{"term":"plate","meaning":"طبق","example":"Put the apple on the plate.","number":194,"id":"a1:194","level":"A1","lessonId":"a1-set-08"},{"term":"bowl","meaning":"وعاء","example":"The cat drinks from a bowl.","number":195,"id":"a1:195","level":"A1","lessonId":"a1-set-08"},{"term":"glass","meaning":"كوب زجاجي","example":"I fill a glass with water.","number":196,"id":"a1:196","level":"A1","lessonId":"a1-set-08"},{"term":"bottle","meaning":"زجاجة","example":"Close the bottle tightly.","number":197,"id":"a1:197","level":"A1","lessonId":"a1-set-08"},{"term":"kettle","meaning":"غلاية","example":"The kettle heats water for tea.","number":198,"id":"a1:198","level":"A1","lessonId":"a1-set-08"},{"term":"pan","meaning":"مقلاة","example":"Mum cooks eggs in a pan.","number":199,"id":"a1:199","level":"A1","lessonId":"a1-set-08"},{"term":"pot","meaning":"قدر","example":"The soup is bubbling in the pot.","number":200,"id":"a1:200","level":"A1","lessonId":"a1-set-08"}],"story":{"title":"The Midnight Kitchen Surprise","paragraphs":["At a little party, the children wanted a milkshake, cola, smoothie, cocoa, or soda. There was a cake on the table, a cookie on a small plate, and a biscuit in a tin. There were also chocolate, candy, ice cream, and pudding. Nina brought honey and jam, but Grandpa said, 'Please do not add too much sugar!'","Chef Max entered the kitchen with a fork, a spoon, and a safe plastic knife. He put a clean plate beside a bowl and a glass. He filled a bottle with water and checked the kettle. Then he picked up a pan and a pot. 'I have a surprise,' he whispered.","Suddenly the lights went out. Everyone froze. When the lights came on, a tiny pancake tower stood in the middle of the table. Max had made it in the dark using his little lamp! 'How did you do that?' they asked. 'With practice,' he said, 'and a very messy kitchen!'"],"questions":["What did Grandpa warn the children about?","What tools did Chef Max carry?","What happened to the lights?","What was the surprise?"]}},{"id":"a1-set-09","title":"At Home • Rooms and Places • Parts of a House","subtitle":"A1 foundation adventure 09","level":"A1","set":9,"emoji":"🦊","color":"#F6A844","words":[{"term":"sofa","meaning":"أريكة","example":"Our family sits on the sofa.","number":201,"id":"a1:201","level":"A1","lessonId":"a1-set-09"},{"term":"bed","meaning":"سرير","example":"I make my bed every morning.","number":202,"id":"a1:202","level":"A1","lessonId":"a1-set-09"},{"term":"pillow","meaning":"وسادة","example":"My pillow is soft and comfortable.","number":203,"id":"a1:203","level":"A1","lessonId":"a1-set-09"},{"term":"blanket","meaning":"بطانية","example":"I pull the blanket over my feet.","number":204,"id":"a1:204","level":"A1","lessonId":"a1-set-09"},{"term":"lamp","meaning":"مصباح","example":"Switch on the lamp to read.","number":205,"id":"a1:205","level":"A1","lessonId":"a1-set-09"},{"term":"mirror","meaning":"مرآة","example":"I can see my face in the mirror.","number":206,"id":"a1:206","level":"A1","lessonId":"a1-set-09"},{"term":"clock","meaning":"ساعة حائط","example":"The clock shows eight o'clock.","number":207,"id":"a1:207","level":"A1","lessonId":"a1-set-09"},{"term":"carpet","meaning":"سجادة","example":"The children sit on the carpet.","number":208,"id":"a1:208","level":"A1","lessonId":"a1-set-09"},{"term":"curtain","meaning":"ستارة","example":"Open the curtain to let light in.","number":209,"id":"a1:209","level":"A1","lessonId":"a1-set-09"},{"term":"shelf","meaning":"رف","example":"Put the books on the shelf.","number":210,"id":"a1:210","level":"A1","lessonId":"a1-set-09"},{"term":"house","meaning":"منزل","example":"Our house has a green door.","number":211,"id":"a1:211","level":"A1","lessonId":"a1-set-09"},{"term":"room","meaning":"غرفة","example":"My room has two windows.","number":212,"id":"a1:212","level":"A1","lessonId":"a1-set-09"},{"term":"kitchen","meaning":"مطبخ","example":"My family cooks in the kitchen.","number":213,"id":"a1:213","level":"A1","lessonId":"a1-set-09"},{"term":"bathroom","meaning":"حمام","example":"Please wash your hands in the bathroom.","number":214,"id":"a1:214","level":"A1","lessonId":"a1-set-09"},{"term":"bedroom","meaning":"غرفة نوم","example":"I keep my toys in my bedroom.","number":215,"id":"a1:215","level":"A1","lessonId":"a1-set-09"},{"term":"living room","meaning":"غرفة معيشة","example":"We watch a film in the living room.","number":216,"id":"a1:216","level":"A1","lessonId":"a1-set-09"},{"term":"hallway","meaning":"ممر","example":"Our shoes are in the hallway.","number":217,"id":"a1:217","level":"A1","lessonId":"a1-set-09"},{"term":"garden","meaning":"حديقة","example":"We water flowers in the garden.","number":218,"id":"a1:218","level":"A1","lessonId":"a1-set-09"},{"term":"garage","meaning":"مرآب","example":"Dad parks the car in the garage.","number":219,"id":"a1:219","level":"A1","lessonId":"a1-set-09"},{"term":"balcony","meaning":"شرفة","example":"We can see the park from the balcony.","number":220,"id":"a1:220","level":"A1","lessonId":"a1-set-09"},{"term":"door","meaning":"باب","example":"Please close the door quietly.","number":221,"id":"a1:221","level":"A1","lessonId":"a1-set-09"},{"term":"window","meaning":"نافذة","example":"A bird sits outside the window.","number":222,"id":"a1:222","level":"A1","lessonId":"a1-set-09"},{"term":"wall","meaning":"جدار","example":"There is a picture on the wall.","number":223,"id":"a1:223","level":"A1","lessonId":"a1-set-09"},{"term":"floor","meaning":"أرضية","example":"I sweep the floor after lunch.","number":224,"id":"a1:224","level":"A1","lessonId":"a1-set-09"},{"term":"roof","meaning":"سقف خارجي","example":"The bird lands on the roof.","number":225,"id":"a1:225","level":"A1","lessonId":"a1-set-09"}],"story":{"title":"The House with a Secret Room","paragraphs":["Ella had just moved into a new house. In the living room she saw a sofa, a soft carpet, and a strange clock. Upstairs she found a bed, a pillow, and a warm blanket. A lamp stood by the mirror. A blue curtain covered the window, and a small shelf held one old book.","Ella explored every room. She visited the kitchen, bathroom, and bedroom. She walked along the hallway and looked into the garden. The garage was empty, and the balcony had a lovely view. She counted each door and checked every wall, the floor, and even the roof through the attic window.","Just then, the clock rang thirteen times! 'That is impossible,' Ella whispered. A tiny key fell from behind the clock and landed on the carpet. She tried it in a little wooden door behind the shelf. Click! Inside was a secret reading room full of colorful books. Ella smiled. 'This is my favorite part of our new home.'"],"questions":["What was strange about the clock?","Where did Ella find the key?","What did the key open?","How did Ella feel at the end?"]}},{"id":"a1-set-10","title":"Parts of a House • My School Bag • In the Classroom","subtitle":"A1 foundation adventure 10","level":"A1","set":10,"emoji":"🦊","color":"#F6A844","words":[{"term":"stairs","meaning":"درج","example":"Walk slowly on the stairs.","number":226,"id":"a1:226","level":"A1","lessonId":"a1-set-10"},{"term":"ceiling","meaning":"سقف داخلي","example":"A lamp hangs from the ceiling.","number":227,"id":"a1:227","level":"A1","lessonId":"a1-set-10"},{"term":"gate","meaning":"بوابة","example":"Open the gate to enter the garden.","number":228,"id":"a1:228","level":"A1","lessonId":"a1-set-10"},{"term":"fence","meaning":"سياج","example":"A goat jumps over the fence.","number":229,"id":"a1:229","level":"A1","lessonId":"a1-set-10"},{"term":"key","meaning":"مفتاح","example":"I use my key to open the door.","number":230,"id":"a1:230","level":"A1","lessonId":"a1-set-10"},{"term":"book","meaning":"كتاب","example":"This book has a funny story.","number":231,"id":"a1:231","level":"A1","lessonId":"a1-set-10"},{"term":"notebook","meaning":"دفتر","example":"I write new words in my notebook.","number":232,"id":"a1:232","level":"A1","lessonId":"a1-set-10"},{"term":"pencil","meaning":"قلم رصاص","example":"Sharpen your pencil before writing.","number":233,"id":"a1:233","level":"A1","lessonId":"a1-set-10"},{"term":"pen","meaning":"قلم","example":"Use a blue pen to write your name.","number":234,"id":"a1:234","level":"A1","lessonId":"a1-set-10"},{"term":"ruler","meaning":"مسطرة","example":"Measure the line with a ruler.","number":235,"id":"a1:235","level":"A1","lessonId":"a1-set-10"},{"term":"eraser","meaning":"ممحاة","example":"An eraser removes pencil marks.","number":236,"id":"a1:236","level":"A1","lessonId":"a1-set-10"},{"term":"sharpener","meaning":"براية","example":"My sharpener has two holes.","number":237,"id":"a1:237","level":"A1","lessonId":"a1-set-10"},{"term":"crayon","meaning":"قلم تلوين","example":"I draw a rainbow with a crayon.","number":238,"id":"a1:238","level":"A1","lessonId":"a1-set-10"},{"term":"paper","meaning":"ورق","example":"This paper is white.","number":239,"id":"a1:239","level":"A1","lessonId":"a1-set-10"},{"term":"backpack","meaning":"حقيبة ظهر","example":"My backpack is heavy.","number":240,"id":"a1:240","level":"A1","lessonId":"a1-set-10"},{"term":"desk","meaning":"مكتب دراسي","example":"Keep your desk neat and tidy.","number":241,"id":"a1:241","level":"A1","lessonId":"a1-set-10"},{"term":"board","meaning":"سبورة","example":"The teacher draws a circle on the board.","number":242,"id":"a1:242","level":"A1","lessonId":"a1-set-10"},{"term":"chalk","meaning":"طباشير","example":"I write with chalk.","number":243,"id":"a1:243","level":"A1","lessonId":"a1-set-10"},{"term":"marker","meaning":"قلم تخطيط","example":"Write the title with a black marker.","number":244,"id":"a1:244","level":"A1","lessonId":"a1-set-10"},{"term":"glue","meaning":"صمغ","example":"The glue is sticky.","number":245,"id":"a1:245","level":"A1","lessonId":"a1-set-10"},{"term":"scissors","meaning":"مقص","example":"Use scissors carefully.","number":246,"id":"a1:246","level":"A1","lessonId":"a1-set-10"},{"term":"paintbrush","meaning":"فرشاة رسم","example":"Dip the paintbrush in water.","number":247,"id":"a1:247","level":"A1","lessonId":"a1-set-10"},{"term":"map","meaning":"خريطة","example":"Find the town on the map.","number":248,"id":"a1:248","level":"A1","lessonId":"a1-set-10"},{"term":"dictionary","meaning":"قاموس","example":"A dictionary helps us learn words.","number":249,"id":"a1:249","level":"A1","lessonId":"a1-set-10"},{"term":"workbook","meaning":"كتاب أنشطة","example":"Complete page five in your workbook.","number":250,"id":"a1:250","level":"A1","lessonId":"a1-set-10"}],"story":{"title":"The Missing Classroom Map","paragraphs":["On Monday, a classroom map disappeared! Miss Lee stood by the stairs and looked at the ceiling. She checked the school gate, the fence, and the lost-and-found box. 'Maybe a key will help us open the cupboard,' she said.","Mia opened her backpack. She had a book, a notebook, a pencil, a pen, a ruler, an eraser, a sharpener, a crayon, and a sheet of paper. On the desk were the board marker, some chalk, glue, scissors, and a paintbrush. Her friend used the dictionary to find the word 'map' in the workbook.","Then Mia noticed blue paint on the floor. The paint marks went from the board to the cupboard. 'Follow the little footprints!' she said. The class opened the cupboard and found the missing map. It was stuck to the back of a giant cardboard rocket. Everyone laughed. Miss Lee said, 'A good detective always looks carefully!'"],"questions":["What was missing?","What did Mia find on the floor?","Where was the map hiding?","What did Miss Lee say detectives should do?"]}},{"id":"a1-set-11","title":"Toys and Games • Sports • Move and Play","subtitle":"A1 foundation adventure 11","level":"A1","set":11,"emoji":"🦊","color":"#F6A844","words":[{"term":"ball","meaning":"كرة","example":"Leo kicks the ball into the goal.","number":251,"id":"a1:251","level":"A1","lessonId":"a1-set-11"},{"term":"kite","meaning":"طائرة ورقية","example":"Our kite flies high in the wind.","number":252,"id":"a1:252","level":"A1","lessonId":"a1-set-11"},{"term":"doll","meaning":"دمية","example":"The doll wears a tiny hat.","number":253,"id":"a1:253","level":"A1","lessonId":"a1-set-11"},{"term":"teddy bear","meaning":"دب محشو","example":"My teddy bear sits on the bed.","number":254,"id":"a1:254","level":"A1","lessonId":"a1-set-11"},{"term":"toy","meaning":"لعبة","example":"Put each toy in the box.","number":255,"id":"a1:255","level":"A1","lessonId":"a1-set-11"},{"term":"puzzle","meaning":"أحجية","example":"We complete the puzzle together.","number":256,"id":"a1:256","level":"A1","lessonId":"a1-set-11"},{"term":"swing","meaning":"أرجوحة","example":"Maha moves high on the swing.","number":257,"id":"a1:257","level":"A1","lessonId":"a1-set-11"},{"term":"slide","meaning":"زحليقة","example":"The children go down the slide.","number":258,"id":"a1:258","level":"A1","lessonId":"a1-set-11"},{"term":"seesaw","meaning":"أرجوحة توازن","example":"Two friends sit on the seesaw.","number":259,"id":"a1:259","level":"A1","lessonId":"a1-set-11"},{"term":"skateboard","meaning":"لوح تزلج","example":"Wear a helmet on your skateboard.","number":260,"id":"a1:260","level":"A1","lessonId":"a1-set-11"},{"term":"football","meaning":"كرة القدم","example":"We play football after school.","number":261,"id":"a1:261","level":"A1","lessonId":"a1-set-11"},{"term":"basketball","meaning":"كرة السلة","example":"Throw the basketball into the hoop.","number":262,"id":"a1:262","level":"A1","lessonId":"a1-set-11"},{"term":"tennis","meaning":"التنس","example":"A racket is used in tennis.","number":263,"id":"a1:263","level":"A1","lessonId":"a1-set-11"},{"term":"volleyball","meaning":"الكرة الطائرة","example":"We hit the ball in volleyball.","number":264,"id":"a1:264","level":"A1","lessonId":"a1-set-11"},{"term":"badminton","meaning":"الريشة الطائرة","example":"A shuttlecock is used in badminton.","number":265,"id":"a1:265","level":"A1","lessonId":"a1-set-11"},{"term":"baseball","meaning":"البيسبول","example":"I hit the ball with a bat in baseball.","number":266,"id":"a1:266","level":"A1","lessonId":"a1-set-11"},{"term":"golf","meaning":"الغولف","example":"A small white ball is used in golf.","number":267,"id":"a1:267","level":"A1","lessonId":"a1-set-11"},{"term":"hockey","meaning":"الهوكي","example":"Players use sticks in hockey.","number":268,"id":"a1:268","level":"A1","lessonId":"a1-set-11"},{"term":"boxing","meaning":"الملاكمة","example":"Wear gloves when learning boxing.","number":269,"id":"a1:269","level":"A1","lessonId":"a1-set-11"},{"term":"skiing","meaning":"التزلج على الثلج","example":"People enjoy skiing on snowy mountains.","number":270,"id":"a1:270","level":"A1","lessonId":"a1-set-11"},{"term":"move","meaning":"يتحرك","example":"The little crab can move sideways.","number":271,"id":"a1:271","level":"A1","lessonId":"a1-set-11"},{"term":"walk","meaning":"يمشي","example":"We walk to the nearby park.","number":272,"id":"a1:272","level":"A1","lessonId":"a1-set-11"},{"term":"run","meaning":"يجري","example":"I run quickly to catch the ball.","number":273,"id":"a1:273","level":"A1","lessonId":"a1-set-11"},{"term":"jump","meaning":"يقفز","example":"Watch the rabbit jump over a log.","number":274,"id":"a1:274","level":"A1","lessonId":"a1-set-11"},{"term":"sit","meaning":"يجلس","example":"Please sit on your chair.","number":275,"id":"a1:275","level":"A1","lessonId":"a1-set-11"}],"story":{"title":"The Playground Olympics","paragraphs":["At the playground, Max held a ball while Zoe flew a kite. A doll and a teddy bear watched from the bench. Max put down his favorite toy and opened a puzzle. 'We need a new game!' he said. There was a swing, a slide, a seesaw, and a skateboard nearby.","The friends invented silly Olympics. First came football and basketball, then tennis, volleyball, and badminton. At another corner they tried baseball, golf, and hockey. A teacher showed them safe boxing moves, and a pretend skiing race made everyone laugh.","'Ready, move!' shouted Zoe. The children began to walk, then run, and finally jump over a soft rope. Max tried to sit on a rolling skateboard and fell gently into a pile of cushions. 'I think sitting is my best sport!' he laughed. Everyone cheered for the silliest competition ever."],"questions":["Where were the children playing?","What did they invent?","What did Max fall into?","Why did everyone cheer?"]}},{"id":"a1-set-12","title":"Move and Play • Daily Actions • Learning Actions","subtitle":"A1 foundation adventure 12","level":"A1","set":12,"emoji":"🦊","color":"#F6A844","words":[{"term":"stand","meaning":"يقف","example":"We stand when the teacher enters.","number":276,"id":"a1:276","level":"A1","lessonId":"a1-set-12"},{"term":"stop","meaning":"يتوقف","example":"The red light means stop.","number":277,"id":"a1:277","level":"A1","lessonId":"a1-set-12"},{"term":"go","meaning":"يذهب","example":"We go to the zoo on Friday.","number":278,"id":"a1:278","level":"A1","lessonId":"a1-set-12"},{"term":"come","meaning":"يأتي","example":"Please come to the front of the class.","number":279,"id":"a1:279","level":"A1","lessonId":"a1-set-12"},{"term":"turn","meaning":"يلتفت","example":"Turn the page to see a new story.","number":280,"id":"a1:280","level":"A1","lessonId":"a1-set-12"},{"term":"eat","meaning":"يأكل","example":"I eat an apple at break time.","number":281,"id":"a1:281","level":"A1","lessonId":"a1-set-12"},{"term":"drink","meaning":"يشرب","example":"We drink water after exercise.","number":282,"id":"a1:282","level":"A1","lessonId":"a1-set-12"},{"term":"sleep","meaning":"ينام","example":"I sleep early on school nights.","number":283,"id":"a1:283","level":"A1","lessonId":"a1-set-12"},{"term":"wake","meaning":"يستيقظ","example":"I wake up when my alarm rings.","number":284,"id":"a1:284","level":"A1","lessonId":"a1-set-12"},{"term":"wash","meaning":"يغسل","example":"Remember to wash your hands.","number":285,"id":"a1:285","level":"A1","lessonId":"a1-set-12"},{"term":"brush","meaning":"يفرش","example":"I brush my teeth twice a day.","number":286,"id":"a1:286","level":"A1","lessonId":"a1-set-12"},{"term":"comb","meaning":"يمشط","example":"I comb my hair before school.","number":287,"id":"a1:287","level":"A1","lessonId":"a1-set-12"},{"term":"cook","meaning":"يطبخ","example":"We cook rice for lunch.","number":288,"id":"a1:288","level":"A1","lessonId":"a1-set-12"},{"term":"clean","meaning":"ينظف","example":"Please clean your desk after painting.","number":289,"id":"a1:289","level":"A1","lessonId":"a1-set-12"},{"term":"rest","meaning":"يستريح","example":"We rest after a long walk.","number":290,"id":"a1:290","level":"A1","lessonId":"a1-set-12"},{"term":"read","meaning":"يقرأ","example":"I read a funny book every night.","number":291,"id":"a1:291","level":"A1","lessonId":"a1-set-12"},{"term":"write","meaning":"يكتب","example":"I write my name carefully.","number":292,"id":"a1:292","level":"A1","lessonId":"a1-set-12"},{"term":"draw","meaning":"يرسم","example":"Can you draw a big elephant?","number":293,"id":"a1:293","level":"A1","lessonId":"a1-set-12"},{"term":"paint","meaning":"يلون","example":"We paint a picture of a tree.","number":294,"id":"a1:294","level":"A1","lessonId":"a1-set-12"},{"term":"count","meaning":"يعد","example":"I count the stars in the sky.","number":295,"id":"a1:295","level":"A1","lessonId":"a1-set-12"},{"term":"spell","meaning":"يتهجى","example":"Can you spell your friend's name?","number":296,"id":"a1:296","level":"A1","lessonId":"a1-set-12"},{"term":"listen","meaning":"يستمع","example":"We listen to the teacher's story.","number":297,"id":"a1:297","level":"A1","lessonId":"a1-set-12"},{"term":"speak","meaning":"يتحدث","example":"Please speak clearly and slowly.","number":298,"id":"a1:298","level":"A1","lessonId":"a1-set-12"},{"term":"sing","meaning":"يغني","example":"We sing a song together.","number":299,"id":"a1:299","level":"A1","lessonId":"a1-set-12"},{"term":"learn","meaning":"يتعلم","example":"I learn three new words today.","number":300,"id":"a1:300","level":"A1","lessonId":"a1-set-12"}],"story":{"title":"A Day at the Talking School","paragraphs":["At a very special school, the bell could speak. 'Stand up, stop, and listen!' it said. 'Now go to class, come inside, and turn to the window.' The children laughed because the bell sounded like a tiny robot.","Their teacher made a plan for the day. First they would eat breakfast and drink water. Then they would talk about sleep and what time they wake. After that they would wash their hands, brush their teeth, and comb their hair. At lunch, they would help cook, clean the tables, and rest for a few minutes.","In the afternoon the class would read a story, write a note, draw a robot, and paint a picture. They would count the stars, spell new words, listen to a song, speak in pairs, and sing together. 'Today we will learn many things,' said the bell. At last it played a funny tune. 'Time to go home!' it announced, and everyone waved goodbye."],"questions":["What could speak at the school?","What did the children do after washing?","What did they paint?","How did the school day end?"]}},{"id":"a1-set-13","title":"Talk and Smile • Feelings • Big and Small","subtitle":"A1 foundation adventure 13","level":"A1","set":13,"emoji":"🦊","color":"#F6A844","words":[{"term":"say","meaning":"يقول","example":"Please say the word aloud.","number":301,"id":"a1:301","level":"A1","lessonId":"a1-set-13"},{"term":"tell","meaning":"يخبر","example":"Can you tell me a story?","number":302,"id":"a1:302","level":"A1","lessonId":"a1-set-13"},{"term":"ask","meaning":"يسأل","example":"Raise your hand to ask a question.","number":303,"id":"a1:303","level":"A1","lessonId":"a1-set-13"},{"term":"answer","meaning":"يجيب","example":"Think before you answer.","number":304,"id":"a1:304","level":"A1","lessonId":"a1-set-13"},{"term":"talk","meaning":"يتكلم","example":"We talk quietly in the library.","number":305,"id":"a1:305","level":"A1","lessonId":"a1-set-13"},{"term":"call","meaning":"ينادي","example":"Please call your friend by name.","number":306,"id":"a1:306","level":"A1","lessonId":"a1-set-13"},{"term":"shout","meaning":"يصرخ","example":"Do not shout in the classroom.","number":307,"id":"a1:307","level":"A1","lessonId":"a1-set-13"},{"term":"whisper","meaning":"يهمس","example":"We whisper during the game.","number":308,"id":"a1:308","level":"A1","lessonId":"a1-set-13"},{"term":"smile","meaning":"يبتسم","example":"I smile when I see my mother.","number":309,"id":"a1:309","level":"A1","lessonId":"a1-set-13"},{"term":"laugh","meaning":"يضحك","example":"The funny goat makes us laugh.","number":310,"id":"a1:310","level":"A1","lessonId":"a1-set-13"},{"term":"happy","meaning":"سعيد","example":"I feel happy when I play with friends.","number":311,"id":"a1:311","level":"A1","lessonId":"a1-set-13"},{"term":"sad","meaning":"حزين","example":"The child feels sad when the toy breaks.","number":312,"id":"a1:312","level":"A1","lessonId":"a1-set-13"},{"term":"angry","meaning":"غاضب","example":"I take a deep breath when I feel angry.","number":313,"id":"a1:313","level":"A1","lessonId":"a1-set-13"},{"term":"scared","meaning":"خائف","example":"The kitten is scared of the thunder.","number":314,"id":"a1:314","level":"A1","lessonId":"a1-set-13"},{"term":"excited","meaning":"متحمس","example":"We are excited about the school trip.","number":315,"id":"a1:315","level":"A1","lessonId":"a1-set-13"},{"term":"tired","meaning":"متعب","example":"I feel tired after running.","number":316,"id":"a1:316","level":"A1","lessonId":"a1-set-13"},{"term":"hungry","meaning":"جائع","example":"The hungry rabbit looks for a carrot.","number":317,"id":"a1:317","level":"A1","lessonId":"a1-set-13"},{"term":"thirsty","meaning":"عطشان","example":"I am thirsty after football.","number":318,"id":"a1:318","level":"A1","lessonId":"a1-set-13"},{"term":"surprised","meaning":"متفاجئ","example":"Maha is surprised by the birthday cake.","number":319,"id":"a1:319","level":"A1","lessonId":"a1-set-13"},{"term":"bored","meaning":"ضجر","example":"I feel bored when there is nothing to do.","number":320,"id":"a1:320","level":"A1","lessonId":"a1-set-13"},{"term":"big","meaning":"كبير","example":"A big elephant walks past the tree.","number":321,"id":"a1:321","level":"A1","lessonId":"a1-set-13"},{"term":"small","meaning":"صغير","example":"A small bird sits on the fence.","number":322,"id":"a1:322","level":"A1","lessonId":"a1-set-13"},{"term":"tall","meaning":"طويل القامة","example":"The tall giraffe eats leaves.","number":323,"id":"a1:323","level":"A1","lessonId":"a1-set-13"},{"term":"short","meaning":"قصير","example":"My pencil is too short to use.","number":324,"id":"a1:324","level":"A1","lessonId":"a1-set-13"},{"term":"long","meaning":"طويل","example":"The long train has many cars.","number":325,"id":"a1:325","level":"A1","lessonId":"a1-set-13"}],"story":{"title":"The Whispering Giant","paragraphs":["'Can I say something?' asked Pip, a small mouse. 'Of course,' said the big giant. 'You may tell me anything.' Pip wanted to ask a question, but the giant did not hear his answer. 'Please talk louder,' said the giant. Pip tried to call his friend, then shout, but only a whisper came out.","Pip began to smile. The giant started to laugh, too. Then Pip looked sad. 'I am not happy. I am angry because no one hears me.' The giant felt scared for a moment, then excited about helping. 'You look tired, hungry, and thirsty,' he said. Pip was surprised to hear such kind words. 'I was bored, but now I have a friend,' he replied.","The giant found a long tube and a short one. He was tall enough to hold one end high in the air, while Pip spoke into the other. 'Hello!' Pip called. The sound became huge! A little bird looked up. The giant had made a big voice for a small friend. 'What a wonderful idea!' cried Pip."],"questions":["What problem did Pip have?","How did the giant help?","What happened when Pip spoke through it?","How did Pip feel in the end?"]}},{"id":"a1-set-14","title":"Big and Small • Describing Things • Shapes","subtitle":"A1 foundation adventure 14","level":"A1","set":14,"emoji":"🦊","color":"#F6A844","words":[{"term":"tiny","meaning":"صغير جدا","example":"A tiny ant crawls on the leaf.","number":326,"id":"a1:326","level":"A1","lessonId":"a1-set-14"},{"term":"huge","meaning":"ضخم","example":"A huge whale swims in the ocean.","number":327,"id":"a1:327","level":"A1","lessonId":"a1-set-14"},{"term":"little","meaning":"صغير","example":"The little boy waves to his mother.","number":328,"id":"a1:328","level":"A1","lessonId":"a1-set-14"},{"term":"wide","meaning":"واسع","example":"The river is wide after the rain.","number":329,"id":"a1:329","level":"A1","lessonId":"a1-set-14"},{"term":"narrow","meaning":"ضيق","example":"The narrow bridge crosses the stream.","number":330,"id":"a1:330","level":"A1","lessonId":"a1-set-14"},{"term":"hot","meaning":"حار","example":"Be careful: the soup is hot.","number":331,"id":"a1:331","level":"A1","lessonId":"a1-set-14"},{"term":"cold","meaning":"بارد","example":"My hands feel cold in winter.","number":332,"id":"a1:332","level":"A1","lessonId":"a1-set-14"},{"term":"warm","meaning":"دافئ","example":"A warm blanket feels comfortable.","number":333,"id":"a1:333","level":"A1","lessonId":"a1-set-14"},{"term":"cool","meaning":"معتدل البرودة","example":"A cool breeze blows in the evening.","number":334,"id":"a1:334","level":"A1","lessonId":"a1-set-14"},{"term":"wet","meaning":"مبلل","example":"My shoes are wet after the rain.","number":335,"id":"a1:335","level":"A1","lessonId":"a1-set-14"},{"term":"dry","meaning":"جاف","example":"Leave the shirt outside to dry.","number":336,"id":"a1:336","level":"A1","lessonId":"a1-set-14"},{"term":"clear","meaning":"صاف","example":"The sky is clear after the storm.","number":337,"id":"a1:337","level":"A1","lessonId":"a1-set-14"},{"term":"dirty","meaning":"متسخ","example":"Please wash your dirty hands.","number":338,"id":"a1:338","level":"A1","lessonId":"a1-set-14"},{"term":"full","meaning":"ممتلئ","example":"The bottle is full of water.","number":339,"id":"a1:339","level":"A1","lessonId":"a1-set-14"},{"term":"empty","meaning":"فارغ","example":"The lunch box is empty now.","number":340,"id":"a1:340","level":"A1","lessonId":"a1-set-14"},{"term":"circle","meaning":"دائرة","example":"A wheel looks like a circle.","number":341,"id":"a1:341","level":"A1","lessonId":"a1-set-14"},{"term":"square","meaning":"مربع","example":"Draw a square with four equal sides.","number":342,"id":"a1:342","level":"A1","lessonId":"a1-set-14"},{"term":"triangle","meaning":"مثلث","example":"A triangle has three sides.","number":343,"id":"a1:343","level":"A1","lessonId":"a1-set-14"},{"term":"rectangle","meaning":"مستطيل","example":"A door is shaped like a rectangle.","number":344,"id":"a1:344","level":"A1","lessonId":"a1-set-14"},{"term":"oval","meaning":"شكل بيضاوي","example":"An egg looks like an oval.","number":345,"id":"a1:345","level":"A1","lessonId":"a1-set-14"},{"term":"heart","meaning":"قلب","example":"Maha draws a heart for her mother.","number":346,"id":"a1:346","level":"A1","lessonId":"a1-set-14"},{"term":"diamond","meaning":"معين","example":"A diamond shape has four sides.","number":347,"id":"a1:347","level":"A1","lessonId":"a1-set-14"},{"term":"cube","meaning":"مكعب","example":"A dice is shaped like a cube.","number":348,"id":"a1:348","level":"A1","lessonId":"a1-set-14"},{"term":"line","meaning":"خط","example":"Draw a straight line with a ruler.","number":349,"id":"a1:349","level":"A1","lessonId":"a1-set-14"},{"term":"dot","meaning":"نقطة","example":"Put a dot beside the correct answer.","number":350,"id":"a1:350","level":"A1","lessonId":"a1-set-14"}],"story":{"title":"The Giant Shape Machine","paragraphs":["In art class, Professor Dot showed the children a tiny machine. It could make a huge picture from a little mark! 'Watch this,' she said, drawing a short line in a wide box. The machine hummed inside a narrow tunnel. Soon a bright circle appeared, followed by a square, a triangle, a rectangle, and an oval.","Next the machine drew a heart, a diamond, and a cube. Then it made a single dot on a long strip of paper. 'Is this all?' asked Mia. The teacher smiled. 'The paper is dry now, but it will change when it becomes wet.' She put one drop of cold water on it. Colors spread like magic. The paper felt cool, and the ink looked clear.","Suddenly the machine became hot. The room was warm, the table was dirty, and the water bottle was empty. 'Oh dear!' said Professor Dot. She filled the bottle, wiped the table, and let the machine rest. 'When the bottle is full again, we can make more art.' The class cheered for the silly little shape machine."],"questions":["What could the machine make?","What happened when the paper got wet?","Why did the machine need a rest?","Who cleaned the table?"]}},{"id":"a1-set-15","title":"Parts of the Day • Days and Events • Months: Part One","subtitle":"A1 foundation adventure 15","level":"A1","set":15,"emoji":"🦊","color":"#F6A844","words":[{"term":"day","meaning":"يوم","example":"Today is a good day.","number":351,"id":"a1:351","level":"A1","lessonId":"a1-set-15"},{"term":"night","meaning":"ليل","example":"The stars shine at night.","number":352,"id":"a1:352","level":"A1","lessonId":"a1-set-15"},{"term":"morning","meaning":"صباح","example":"I get up in the morning.","number":353,"id":"a1:353","level":"A1","lessonId":"a1-set-15"},{"term":"afternoon","meaning":"بعد الظهر","example":"We play in the afternoon.","number":354,"id":"a1:354","level":"A1","lessonId":"a1-set-15"},{"term":"evening","meaning":"مساء","example":"We eat in the evening.","number":355,"id":"a1:355","level":"A1","lessonId":"a1-set-15"},{"term":"today","meaning":"اليوم","example":"I am happy today.","number":356,"id":"a1:356","level":"A1","lessonId":"a1-set-15"},{"term":"tomorrow","meaning":"غدا","example":"See you tomorrow!","number":357,"id":"a1:357","level":"A1","lessonId":"a1-set-15"},{"term":"yesterday","meaning":"أمس","example":"I played yesterday.","number":358,"id":"a1:358","level":"A1","lessonId":"a1-set-15"},{"term":"week","meaning":"أسبوع","example":"A week has seven days.","number":359,"id":"a1:359","level":"A1","lessonId":"a1-set-15"},{"term":"weekend","meaning":"عطلة نهاية الأسبوع","example":"We rest on the weekend.","number":360,"id":"a1:360","level":"A1","lessonId":"a1-set-15"},{"term":"Monday","meaning":"الاثنين","example":"We have English class on Monday.","number":361,"id":"a1:361","level":"A1","lessonId":"a1-set-15"},{"term":"Tuesday","meaning":"الثلاثاء","example":"Our art lesson is on Tuesday.","number":362,"id":"a1:362","level":"A1","lessonId":"a1-set-15"},{"term":"Wednesday","meaning":"الأربعاء","example":"We read a story on Wednesday.","number":363,"id":"a1:363","level":"A1","lessonId":"a1-set-15"},{"term":"Thursday","meaning":"الخميس","example":"I pack my bag on Thursday.","number":364,"id":"a1:364","level":"A1","lessonId":"a1-set-15"},{"term":"Friday","meaning":"الجمعة","example":"We visit our grandparents on Friday.","number":365,"id":"a1:365","level":"A1","lessonId":"a1-set-15"},{"term":"Saturday","meaning":"السبت","example":"My football game is on Saturday.","number":366,"id":"a1:366","level":"A1","lessonId":"a1-set-15"},{"term":"Sunday","meaning":"الأحد","example":"School begins again on Sunday.","number":367,"id":"a1:367","level":"A1","lessonId":"a1-set-15"},{"term":"holiday","meaning":"عطلة","example":"We have a holiday soon.","number":368,"id":"a1:368","level":"A1","lessonId":"a1-set-15"},{"term":"birthday","meaning":"عيد ميلاد","example":"My birthday is in June.","number":369,"id":"a1:369","level":"A1","lessonId":"a1-set-15"},{"term":"calendar","meaning":"تقويم","example":"Look at the calendar.","number":370,"id":"a1:370","level":"A1","lessonId":"a1-set-15"},{"term":"January","meaning":"يناير","example":"My birthday is in January.","number":371,"id":"a1:371","level":"A1","lessonId":"a1-set-15"},{"term":"February","meaning":"فبراير","example":"My birthday is in February.","number":372,"id":"a1:372","level":"A1","lessonId":"a1-set-15"},{"term":"March","meaning":"مارس","example":"My birthday is in March.","number":373,"id":"a1:373","level":"A1","lessonId":"a1-set-15"},{"term":"April","meaning":"أبريل","example":"My birthday is in April.","number":374,"id":"a1:374","level":"A1","lessonId":"a1-set-15"},{"term":"May","meaning":"مايو","example":"My birthday is in May.","number":375,"id":"a1:375","level":"A1","lessonId":"a1-set-15"}],"story":{"title":"The Calendar That Ran Backwards","paragraphs":["On Monday morning, Leo found a strange calendar in the school library. It showed Tuesday, Wednesday, Thursday, Friday, Saturday, and Sunday, but the pages were in the wrong order! 'What happened yesterday?' asked Leo. 'And what will happen tomorrow?'","He turned a page, and suddenly it became night. He blinked, and it was day again. He saw the afternoon sun, then an evening sky, and then another bright morning. 'A whole week has flown past!' he gasped. His friend Mia said, 'We only wanted to plan our weekend.'","The calendar showed a holiday and a birthday party. It also had pictures for January, February, March, April, and May. 'Today is still Monday,' said Mia. 'But we have seen so many days!' She carefully put the pages back in order. The clock ticked normally again. Leo laughed. 'Next time we need a plan, let's use a normal calendar!'"],"questions":["Where did Leo find the calendar?","What was wrong with it?","Which event did they want to plan?","How did they fix the problem?"]}},{"id":"a1-set-16","title":"Months: Part One • Time and Dates • Around Town","subtitle":"A1 foundation adventure 16","level":"A1","set":16,"emoji":"🦊","color":"#F6A844","words":[{"term":"June","meaning":"يونيو","example":"My birthday is in June.","number":376,"id":"a1:376","level":"A1","lessonId":"a1-set-16"},{"term":"July","meaning":"يوليو","example":"My birthday is in July.","number":377,"id":"a1:377","level":"A1","lessonId":"a1-set-16"},{"term":"August","meaning":"أغسطس","example":"My birthday is in August.","number":378,"id":"a1:378","level":"A1","lessonId":"a1-set-16"},{"term":"September","meaning":"سبتمبر","example":"My birthday is in September.","number":379,"id":"a1:379","level":"A1","lessonId":"a1-set-16"},{"term":"October","meaning":"أكتوبر","example":"My birthday is in October.","number":380,"id":"a1:380","level":"A1","lessonId":"a1-set-16"},{"term":"November","meaning":"نوفمبر","example":"We talk about November.","number":381,"id":"a1:381","level":"A1","lessonId":"a1-set-16"},{"term":"December","meaning":"ديسمبر","example":"We talk about December.","number":382,"id":"a1:382","level":"A1","lessonId":"a1-set-16"},{"term":"year","meaning":"سنة","example":"A year has twelve months.","number":383,"id":"a1:383","level":"A1","lessonId":"a1-set-16"},{"term":"month","meaning":"شهر","example":"January is a month.","number":384,"id":"a1:384","level":"A1","lessonId":"a1-set-16"},{"term":"date","meaning":"تاريخ","example":"Write the date, please.","number":385,"id":"a1:385","level":"A1","lessonId":"a1-set-16"},{"term":"hour","meaning":"ساعة","example":"An hour has sixty minutes.","number":386,"id":"a1:386","level":"A1","lessonId":"a1-set-16"},{"term":"minute","meaning":"دقيقة","example":"Wait one minute.","number":387,"id":"a1:387","level":"A1","lessonId":"a1-set-16"},{"term":"second","meaning":"ثانية","example":"Wait a second.","number":388,"id":"a1:388","level":"A1","lessonId":"a1-set-16"},{"term":"time","meaning":"وقت","example":"What time is it?","number":389,"id":"a1:389","level":"A1","lessonId":"a1-set-16"},{"term":"season","meaning":"فصل من السنة","example":"Summer is a season.","number":390,"id":"a1:390","level":"A1","lessonId":"a1-set-16"},{"term":"school","meaning":"مدرسة","example":"I go to school.","number":391,"id":"a1:391","level":"A1","lessonId":"a1-set-16"},{"term":"park","meaning":"متنزه","example":"We play under the trees in the park.","number":392,"id":"a1:392","level":"A1","lessonId":"a1-set-16"},{"term":"shop","meaning":"متجر","example":"Maha buys a notebook at the shop.","number":393,"id":"a1:393","level":"A1","lessonId":"a1-set-16"},{"term":"supermarket","meaning":"سوبرماركت","example":"We get vegetables at the supermarket.","number":394,"id":"a1:394","level":"A1","lessonId":"a1-set-16"},{"term":"hospital","meaning":"مستشفى","example":"A nurse works at the hospital.","number":395,"id":"a1:395","level":"A1","lessonId":"a1-set-16"},{"term":"library","meaning":"مكتبة","example":"The library has many interesting books.","number":396,"id":"a1:396","level":"A1","lessonId":"a1-set-16"},{"term":"mosque","meaning":"مسجد","example":"We go to the mosque to pray.","number":397,"id":"a1:397","level":"A1","lessonId":"a1-set-16"},{"term":"restaurant","meaning":"مطعم","example":"We eat rice at a restaurant.","number":398,"id":"a1:398","level":"A1","lessonId":"a1-set-16"},{"term":"market","meaning":"سوق","example":"The market sells fresh fruit.","number":399,"id":"a1:399","level":"A1","lessonId":"a1-set-16"},{"term":"zoo","meaning":"حديقة حيوان","example":"I saw a tall giraffe at the zoo.","number":400,"id":"a1:400","level":"A1","lessonId":"a1-set-16"}],"story":{"title":"The One-Hour Town Adventure","paragraphs":["Every month, the town held a different festival. In June there was a kite parade; in July, a flower show; in August, a book fair. September brought music, October brought pumpkins, November brought lanterns, and December brought a winter party. Zoe circled every date on her calendar. 'This will be a busy year!'","One sunny day, her father gave her a challenge. 'You have one hour to visit as many places as you can. Watch the time. Every minute counts, and even a second can make a difference!' Zoe chose the cool spring season for her adventure.","First she passed the school and park. Then she visited a shop, a supermarket, and a hospital. She waved to the librarian at the library, walked past the mosque, and smelled lunch at a restaurant. At the busy market she bought an apple, then hurried to the zoo. 'What a journey!' she laughed. 'I visited the whole town in one hour!'"],"questions":["What happened in August?","How long was Zoe given?","What did Zoe buy at the market?","Where did her adventure end?"]}},{"id":"a1-set-17","title":"Community Places • Getting Around • Technology at Home","subtitle":"A1 foundation adventure 17","level":"A1","set":17,"emoji":"🦊","color":"#F6A844","words":[{"term":"street","meaning":"شارع","example":"Look both ways before crossing the street.","number":401,"id":"a1:401","level":"A1","lessonId":"a1-set-17"},{"term":"road","meaning":"طريق","example":"The car stops at the red light on the road.","number":402,"id":"a1:402","level":"A1","lessonId":"a1-set-17"},{"term":"bridge","meaning":"جسر","example":"A bridge goes over the river.","number":403,"id":"a1:403","level":"A1","lessonId":"a1-set-17"},{"term":"bus stop","meaning":"موقف حافلات","example":"We wait for the school bus at the bus stop.","number":404,"id":"a1:404","level":"A1","lessonId":"a1-set-17"},{"term":"station","meaning":"محطة","example":"The train leaves the station at nine.","number":405,"id":"a1:405","level":"A1","lessonId":"a1-set-17"},{"term":"airport","meaning":"مطار","example":"Our family arrives early at the airport.","number":406,"id":"a1:406","level":"A1","lessonId":"a1-set-17"},{"term":"bank","meaning":"بنك","example":"My father puts money in the bank.","number":407,"id":"a1:407","level":"A1","lessonId":"a1-set-17"},{"term":"post office","meaning":"مكتب بريد","example":"I send a letter from the post office.","number":408,"id":"a1:408","level":"A1","lessonId":"a1-set-17"},{"term":"pharmacy","meaning":"صيدلية","example":"We buy medicine at the pharmacy.","number":409,"id":"a1:409","level":"A1","lessonId":"a1-set-17"},{"term":"police station","meaning":"مركز شرطة","example":"The police station is near the park.","number":410,"id":"a1:410","level":"A1","lessonId":"a1-set-17"},{"term":"car","meaning":"سيارة","example":"My father washes his car on Friday.","number":411,"id":"a1:411","level":"A1","lessonId":"a1-set-17"},{"term":"bus","meaning":"حافلة","example":"Twenty children ride on the school bus.","number":412,"id":"a1:412","level":"A1","lessonId":"a1-set-17"},{"term":"bicycle","meaning":"دراجة","example":"I wear a helmet on my bicycle.","number":413,"id":"a1:413","level":"A1","lessonId":"a1-set-17"},{"term":"train","meaning":"قطار","example":"The train stops at the next station.","number":414,"id":"a1:414","level":"A1","lessonId":"a1-set-17"},{"term":"taxi","meaning":"سيارة أجرة","example":"We take a taxi to the airport.","number":415,"id":"a1:415","level":"A1","lessonId":"a1-set-17"},{"term":"truck","meaning":"شاحنة","example":"The truck carries heavy boxes.","number":416,"id":"a1:416","level":"A1","lessonId":"a1-set-17"},{"term":"boat","meaning":"قارب","example":"A little boat crosses the lake.","number":417,"id":"a1:417","level":"A1","lessonId":"a1-set-17"},{"term":"ship","meaning":"سفينة","example":"The big ship sails across the sea.","number":418,"id":"a1:418","level":"A1","lessonId":"a1-set-17"},{"term":"plane","meaning":"طائرة","example":"Our plane flies above the clouds.","number":419,"id":"a1:419","level":"A1","lessonId":"a1-set-17"},{"term":"helicopter","meaning":"مروحية","example":"A helicopter can land in a small space.","number":420,"id":"a1:420","level":"A1","lessonId":"a1-set-17"},{"term":"computer","meaning":"حاسوب","example":"We use a computer to learn new words.","number":421,"id":"a1:421","level":"A1","lessonId":"a1-set-17"},{"term":"laptop","meaning":"حاسوب محمول","example":"I put my laptop on the desk.","number":422,"id":"a1:422","level":"A1","lessonId":"a1-set-17"},{"term":"tablet","meaning":"جهاز لوحي","example":"Maha reads a story on her tablet.","number":423,"id":"a1:423","level":"A1","lessonId":"a1-set-17"},{"term":"phone","meaning":"هاتف","example":"My mother calls Grandma on the phone.","number":424,"id":"a1:424","level":"A1","lessonId":"a1-set-17"},{"term":"television","meaning":"تلفاز","example":"We watch an animal show on television.","number":425,"id":"a1:425","level":"A1","lessonId":"a1-set-17"}],"story":{"title":"The Lost Message from the Station","paragraphs":["Ben stood on a busy street with his new computer bag. A little robot had sent him a message: 'Meet me by the bridge on the main road!' Ben waited at the bus stop, then walked to the train station. A bus driver pointed toward the airport, but that was too far. He passed a bank, a post office, a pharmacy, and a police station.","Ben's friend arrived by car. Her sister rode a bicycle, and their uncle drove a truck. They heard a train whistle nearby. 'Maybe the robot went by taxi,' Ben said. 'Or perhaps it took a boat, a ship, a plane, or even a helicopter!'","Ben opened his laptop and tablet to check the map. His phone rang, and the television in a shop window showed a funny robot advertisement. 'Look!' cried his friend. The robot was sitting right beside the bridge, waving at them. It held up a sign: 'The real treasure is finding your friends!'"],"questions":["Where did the robot ask Ben to go?","What did Ben use to check the map?","Where was the robot really waiting?","What was the robot's message about?"]}},{"id":"a1-set-18","title":"Technology at Home • Where Is It? • Directions","subtitle":"A1 foundation adventure 18","level":"A1","set":18,"emoji":"🦊","color":"#F6A844","words":[{"term":"radio","meaning":"مذياع","example":"The radio plays a happy song.","number":426,"id":"a1:426","level":"A1","lessonId":"a1-set-18"},{"term":"camera","meaning":"كاميرا","example":"The camera takes a picture of us.","number":427,"id":"a1:427","level":"A1","lessonId":"a1-set-18"},{"term":"keyboard","meaning":"لوحة مفاتيح","example":"I type my name on the keyboard.","number":428,"id":"a1:428","level":"A1","lessonId":"a1-set-18"},{"term":"screen","meaning":"شاشة","example":"The words appear on the screen.","number":429,"id":"a1:429","level":"A1","lessonId":"a1-set-18"},{"term":"charger","meaning":"شاحن","example":"I plug the phone into its charger.","number":430,"id":"a1:430","level":"A1","lessonId":"a1-set-18"},{"term":"in","meaning":"في","example":"The pen is in the bag.","number":431,"id":"a1:431","level":"A1","lessonId":"a1-set-18"},{"term":"on","meaning":"على","example":"The book is on the desk.","number":432,"id":"a1:432","level":"A1","lessonId":"a1-set-18"},{"term":"under","meaning":"تحت","example":"The cat is under the bed.","number":433,"id":"a1:433","level":"A1","lessonId":"a1-set-18"},{"term":"over","meaning":"فوق","example":"The bird flies over us.","number":434,"id":"a1:434","level":"A1","lessonId":"a1-set-18"},{"term":"behind","meaning":"خلف","example":"The boy is behind the door.","number":435,"id":"a1:435","level":"A1","lessonId":"a1-set-18"},{"term":"beside","meaning":"بجانب","example":"Sit beside me.","number":436,"id":"a1:436","level":"A1","lessonId":"a1-set-18"},{"term":"between","meaning":"بين","example":"Sit between Sara and Ali.","number":437,"id":"a1:437","level":"A1","lessonId":"a1-set-18"},{"term":"next to","meaning":"ملاصق لـ","example":"The bank is next to the shop.","number":438,"id":"a1:438","level":"A1","lessonId":"a1-set-18"},{"term":"near","meaning":"قريب من","example":"My house is near school.","number":439,"id":"a1:439","level":"A1","lessonId":"a1-set-18"},{"term":"far","meaning":"بعيد","example":"The park is far away.","number":440,"id":"a1:440","level":"A1","lessonId":"a1-set-18"},{"term":"left","meaning":"يسار","example":"Turn left here.","number":441,"id":"a1:441","level":"A1","lessonId":"a1-set-18"},{"term":"right","meaning":"يمين","example":"Turn right here.","number":442,"id":"a1:442","level":"A1","lessonId":"a1-set-18"},{"term":"up","meaning":"أعلى","example":"Look up at the sky.","number":443,"id":"a1:443","level":"A1","lessonId":"a1-set-18"},{"term":"down","meaning":"أسفل","example":"Please sit down.","number":444,"id":"a1:444","level":"A1","lessonId":"a1-set-18"},{"term":"inside","meaning":"في الداخل","example":"Come inside now.","number":445,"id":"a1:445","level":"A1","lessonId":"a1-set-18"},{"term":"outside","meaning":"في الخارج","example":"We play outside.","number":446,"id":"a1:446","level":"A1","lessonId":"a1-set-18"},{"term":"here","meaning":"هنا","example":"Come here, please.","number":447,"id":"a1:447","level":"A1","lessonId":"a1-set-18"},{"term":"there","meaning":"هناك","example":"Put it there.","number":448,"id":"a1:448","level":"A1","lessonId":"a1-set-18"},{"term":"front","meaning":"مقدمة","example":"Stand at the front.","number":449,"id":"a1:449","level":"A1","lessonId":"a1-set-18"},{"term":"away","meaning":"بعيدا","example":"Stay away from the road.","number":450,"id":"a1:450","level":"A1","lessonId":"a1-set-18"}],"story":{"title":"The Robot’s Treasure Directions","paragraphs":["Zoe found an old radio, a camera, a keyboard, a screen, and a charger in a box. The screen lit up. A little robot appeared and said, 'I need help! There is a treasure somewhere in this room.'","'Put the camera in the bag,' said the robot. 'Place the radio on the shelf and look under the table. See the kite over the desk? The clue is behind it.' Zoe stood beside her friend. 'The next clue is between the books, next to the clock,' said the robot. 'It is near the window, not far away.'","They turned left, then right. They looked up and down, searched inside the cupboard and outside the door, and came back here. 'Look there, at the front of the room!' cried Zoe. A tiny box was hidden under a cushion. As Zoe opened it, a toy bird flew away. Inside was a note: 'You have followed the directions perfectly. The treasure is your clever teamwork!'"],"questions":["Who gave Zoe directions?","Where was the second clue?","What flew away?","What was the real treasure?"]}},{"id":"a1-set-19","title":"Pronouns • Whose Is It? • Be and Have","subtitle":"A1 foundation adventure 19","level":"A1","set":19,"emoji":"🦊","color":"#F6A844","words":[{"term":"I","meaning":"أنا","example":"I am a student.","number":451,"id":"a1:451","level":"A1","lessonId":"a1-set-19"},{"term":"you","meaning":"أنت","example":"You are my friend.","number":452,"id":"a1:452","level":"A1","lessonId":"a1-set-19"},{"term":"he","meaning":"هو","example":"He can read.","number":453,"id":"a1:453","level":"A1","lessonId":"a1-set-19"},{"term":"she","meaning":"هي","example":"She can sing.","number":454,"id":"a1:454","level":"A1","lessonId":"a1-set-19"},{"term":"it","meaning":"هو أو هي لغير العاقل","example":"It is a cat.","number":455,"id":"a1:455","level":"A1","lessonId":"a1-set-19"},{"term":"we","meaning":"نحن","example":"We love English.","number":456,"id":"a1:456","level":"A1","lessonId":"a1-set-19"},{"term":"they","meaning":"هم","example":"They are playing.","number":457,"id":"a1:457","level":"A1","lessonId":"a1-set-19"},{"term":"me","meaning":"إياي أو لي","example":"Please help me.","number":458,"id":"a1:458","level":"A1","lessonId":"a1-set-19"},{"term":"him","meaning":"إياه أو له","example":"I can see him.","number":459,"id":"a1:459","level":"A1","lessonId":"a1-set-19"},{"term":"her","meaning":"إياها أو لها","example":"I can help her.","number":460,"id":"a1:460","level":"A1","lessonId":"a1-set-19"},{"term":"my","meaning":"خاصتي أو لي","example":"This is my book.","number":461,"id":"a1:461","level":"A1","lessonId":"a1-set-19"},{"term":"your","meaning":"خاصتك أو لك","example":"Is this your bag?","number":462,"id":"a1:462","level":"A1","lessonId":"a1-set-19"},{"term":"his","meaning":"خاصته أو له","example":"His pencil is blue.","number":463,"id":"a1:463","level":"A1","lessonId":"a1-set-19"},{"term":"our","meaning":"خاصتنا أو لنا","example":"Our class is fun.","number":464,"id":"a1:464","level":"A1","lessonId":"a1-set-19"},{"term":"their","meaning":"خاصتهم أو لهم","example":"Their car is red.","number":465,"id":"a1:465","level":"A1","lessonId":"a1-set-19"},{"term":"mine","meaning":"ملكي","example":"This bag is mine.","number":466,"id":"a1:466","level":"A1","lessonId":"a1-set-19"},{"term":"yours","meaning":"ملكك","example":"Is this pen yours?","number":467,"id":"a1:467","level":"A1","lessonId":"a1-set-19"},{"term":"ours","meaning":"ملكنا","example":"This room is ours.","number":468,"id":"a1:468","level":"A1","lessonId":"a1-set-19"},{"term":"theirs","meaning":"ملكهم","example":"That bicycle is theirs.","number":469,"id":"a1:469","level":"A1","lessonId":"a1-set-19"},{"term":"its","meaning":"خاص به لغير العاقل","example":"The cat moves its tail.","number":470,"id":"a1:470","level":"A1","lessonId":"a1-set-19"},{"term":"am","meaning":"أكون","example":"I am happy.","number":471,"id":"a1:471","level":"A1","lessonId":"a1-set-19"},{"term":"is","meaning":"يكون","example":"He is tall.","number":472,"id":"a1:472","level":"A1","lessonId":"a1-set-19"},{"term":"are","meaning":"يكونون","example":"We are ready.","number":473,"id":"a1:473","level":"A1","lessonId":"a1-set-19"},{"term":"was","meaning":"كان","example":"I was at home.","number":474,"id":"a1:474","level":"A1","lessonId":"a1-set-19"},{"term":"were","meaning":"كانوا","example":"They were late.","number":475,"id":"a1:475","level":"A1","lessonId":"a1-set-19"}],"story":{"title":"The Pronoun Puppet Show","paragraphs":["In the school hall, five puppets put on a show. The blue puppet said, 'I am Ben. Who are you?' The red puppet answered, 'He is Max, she is Lily, and it is our little dragon. We are friends, and they are the audience!' A teacher laughed. 'Please tell me about him and her, too.'","Max held up a toy. 'This is my ball. Is that your ball?' Lily shook her head. 'No, his ball is red. Our ball is blue, and their ball is green.' Ben smiled. 'The blue one is mine, the yellow one is yours, and the green one is theirs. The red and blue balls together are ours!' The dragon wagged its tail.","Then the lights went out. 'I was scared,' said Ben. 'We were surprised,' said the others. The lights came on, and everyone cheered. 'That dragon has a very funny trick!' cried Lily. The puppets bowed, and the audience clapped for them."],"questions":["What did the puppets put on?","Which ball did Ben say was his?","What did the dragon do?","What surprised the puppets?"]}},{"id":"a1-set-20","title":"Be and Have • Helping Words • Little Connecting Words","subtitle":"A1 foundation adventure 20","level":"A1","set":20,"emoji":"🦊","color":"#F6A844","words":[{"term":"be","meaning":"يكون","example":"Be kind to others.","number":476,"id":"a1:476","level":"A1","lessonId":"a1-set-20"},{"term":"have","meaning":"لديه أو يملك","example":"I have a new book.","number":477,"id":"a1:477","level":"A1","lessonId":"a1-set-20"},{"term":"has","meaning":"لديه أو يملك","example":"She has a doll.","number":478,"id":"a1:478","level":"A1","lessonId":"a1-set-20"},{"term":"had","meaning":"كان لديه","example":"We had breakfast.","number":479,"id":"a1:479","level":"A1","lessonId":"a1-set-20"},{"term":"do","meaning":"يفعل","example":"I do my homework.","number":480,"id":"a1:480","level":"A1","lessonId":"a1-set-20"},{"term":"does","meaning":"يفعل للمفرد","example":"He does his homework.","number":481,"id":"a1:481","level":"A1","lessonId":"a1-set-20"},{"term":"did","meaning":"فعل","example":"I did my best.","number":482,"id":"a1:482","level":"A1","lessonId":"a1-set-20"},{"term":"can","meaning":"يستطيع","example":"I can swim.","number":483,"id":"a1:483","level":"A1","lessonId":"a1-set-20"},{"term":"cannot","meaning":"لا يستطيع","example":"I cannot fly.","number":484,"id":"a1:484","level":"A1","lessonId":"a1-set-20"},{"term":"will","meaning":"سوف","example":"I will call you.","number":485,"id":"a1:485","level":"A1","lessonId":"a1-set-20"},{"term":"would","meaning":"كان سيـ","example":"I would like some water.","number":486,"id":"a1:486","level":"A1","lessonId":"a1-set-20"},{"term":"shall","meaning":"سوف","example":"Shall we play?","number":487,"id":"a1:487","level":"A1","lessonId":"a1-set-20"},{"term":"should","meaning":"ينبغي","example":"You should sleep early.","number":488,"id":"a1:488","level":"A1","lessonId":"a1-set-20"},{"term":"must","meaning":"يجب","example":"We must be careful.","number":489,"id":"a1:489","level":"A1","lessonId":"a1-set-20"},{"term":"might","meaning":"ربما أو قد","example":"It might rain today.","number":490,"id":"a1:490","level":"A1","lessonId":"a1-set-20"},{"term":"a","meaning":"أداة نكرة","example":"I see a bird.","number":491,"id":"a1:491","level":"A1","lessonId":"a1-set-20"},{"term":"an","meaning":"أداة نكرة","example":"I eat an apple.","number":492,"id":"a1:492","level":"A1","lessonId":"a1-set-20"},{"term":"the","meaning":"الـ التعريف","example":"The book is open.","number":493,"id":"a1:493","level":"A1","lessonId":"a1-set-20"},{"term":"and","meaning":"و","example":"Ali and Maha are friends.","number":494,"id":"a1:494","level":"A1","lessonId":"a1-set-20"},{"term":"but","meaning":"لكن","example":"It is small but strong.","number":495,"id":"a1:495","level":"A1","lessonId":"a1-set-20"},{"term":"or","meaning":"أو","example":"Tea or juice?","number":496,"id":"a1:496","level":"A1","lessonId":"a1-set-20"},{"term":"because","meaning":"لأن","example":"I smile because I am happy.","number":497,"id":"a1:497","level":"A1","lessonId":"a1-set-20"},{"term":"if","meaning":"إذا","example":"Call me if you need help.","number":498,"id":"a1:498","level":"A1","lessonId":"a1-set-20"},{"term":"so","meaning":"لذلك","example":"It is late, so we leave.","number":499,"id":"a1:499","level":"A1","lessonId":"a1-set-20"},{"term":"with","meaning":"مع","example":"I play with my friend.","number":500,"id":"a1:500","level":"A1","lessonId":"a1-set-20"}],"story":{"title":"The Bridge That Could Talk","paragraphs":["A little bridge stood over a stream. 'I want to be strong,' it told the builder. 'I have two big stones, but my friend has only one. We had a storm last night, and I do not know what to do.'","The builder smiled. 'Does the bridge need more wood? Did the rain wash some away? We can help, and we will do our best. We cannot stop the weather, but we can make the bridge safer. I would carry the boards if I were taller. Shall we begin? You should hold this rope. We must work together. It might rain again.'","They found a hammer and an old box with nails. 'Wood or stone?' the bridge asked. The builder put the box on the grass because the ground was dry. 'If we work carefully, the bridge will be safe, so everyone can cross,' he said. A duck watched them, and a frog jumped into the stream. At sunset the bridge was ready. 'Thank you!' it whispered. 'Now I can be a useful bridge again.'"],"questions":["What had damaged the bridge?","What did the builder use to repair it?","Why did they work carefully?","How did the bridge feel at the end?"]}},{"id":"a1-set-21","title":"Daily Life • Active Verbs • At the Shop","subtitle":"A1 foundation adventure 21","level":"A1","set":21,"emoji":"🦊","color":"#F6A844","words":[{"term":"relax","meaning":"يسترخي","example":"I relax after school.","number":501,"id":"a1:501","level":"A1","lessonId":"a1-set-21"},{"term":"tidy","meaning":"يرتب","example":"I tidy my desk.","number":502,"id":"a1:502","level":"A1","lessonId":"a1-set-21"},{"term":"prepare","meaning":"يحضر","example":"We prepare our bags.","number":503,"id":"a1:503","level":"A1","lessonId":"a1-set-21"},{"term":"finish","meaning":"ينهي","example":"Please finish your work.","number":504,"id":"a1:504","level":"A1","lessonId":"a1-set-21"},{"term":"start","meaning":"يبدأ","example":"We start at eight.","number":505,"id":"a1:505","level":"A1","lessonId":"a1-set-21"},{"term":"begin","meaning":"يشرع","example":"The show will begin soon.","number":506,"id":"a1:506","level":"A1","lessonId":"a1-set-21"},{"term":"continue","meaning":"يواصل","example":"Please continue reading.","number":507,"id":"a1:507","level":"A1","lessonId":"a1-set-21"},{"term":"return","meaning":"يعود","example":"I return home at four.","number":508,"id":"a1:508","level":"A1","lessonId":"a1-set-21"},{"term":"leave","meaning":"يغادر","example":"We leave after lunch.","number":509,"id":"a1:509","level":"A1","lessonId":"a1-set-21"},{"term":"arrive","meaning":"يصل","example":"We arrive early.","number":510,"id":"a1:510","level":"A1","lessonId":"a1-set-21"},{"term":"enter","meaning":"يدخل","example":"Enter the classroom.","number":511,"id":"a1:511","level":"A1","lessonId":"a1-set-21"},{"term":"reach","meaning":"يصل إلى","example":"We reach the park at five.","number":512,"id":"a1:512","level":"A1","lessonId":"a1-set-21"},{"term":"cross","meaning":"يعبر","example":"Cross the road carefully.","number":513,"id":"a1:513","level":"A1","lessonId":"a1-set-21"},{"term":"follow","meaning":"يتبع","example":"Follow the teacher.","number":514,"id":"a1:514","level":"A1","lessonId":"a1-set-21"},{"term":"carry","meaning":"يحمل","example":"I carry my bag.","number":515,"id":"a1:515","level":"A1","lessonId":"a1-set-21"},{"term":"push","meaning":"يدفع","example":"Push the door gently.","number":516,"id":"a1:516","level":"A1","lessonId":"a1-set-21"},{"term":"pull","meaning":"يسحب","example":"Pull the handle.","number":517,"id":"a1:517","level":"A1","lessonId":"a1-set-21"},{"term":"lift","meaning":"يرفع","example":"Lift the box carefully.","number":518,"id":"a1:518","level":"A1","lessonId":"a1-set-21"},{"term":"drop","meaning":"يسقط","example":"Do not drop the glass.","number":519,"id":"a1:519","level":"A1","lessonId":"a1-set-21"},{"term":"climb","meaning":"يتسلق","example":"We climb the hill.","number":520,"id":"a1:520","level":"A1","lessonId":"a1-set-21"},{"term":"buy","meaning":"يشتري","example":"I buy a notebook.","number":521,"id":"a1:521","level":"A1","lessonId":"a1-set-21"},{"term":"sell","meaning":"يبيع","example":"They sell fresh fruit.","number":522,"id":"a1:522","level":"A1","lessonId":"a1-set-21"},{"term":"pay","meaning":"يدفع مالا","example":"I pay for the juice.","number":523,"id":"a1:523","level":"A1","lessonId":"a1-set-21"},{"term":"cost","meaning":"يكلف","example":"How much does it cost?","number":524,"id":"a1:524","level":"A1","lessonId":"a1-set-21"},{"term":"price","meaning":"سعر","example":"The price is ten riyals.","number":525,"id":"a1:525","level":"A1","lessonId":"a1-set-21"}],"story":{"title":"The Shop with the Secret Door","paragraphs":["Maya tried to relax, but her room was messy. 'First I will tidy it. Then I can prepare for my adventure,' she said. She wanted to finish her work before the clock struck ten. At last she was ready to start. 'Let's begin!' she cried. She decided to continue down the street, return a library book, and leave a note for her friend.","The note said, 'Arrive at the old shop, enter the small door, and reach for the high shelf. Cross the little bridge, follow a painted arrow, and carry the box. Push one door, pull another, and lift the wooden lid. Do not drop the key. Then climb the short ladder.' Maya followed each instruction carefully.","Behind the shelf was a toy market. A smiling seller wanted to buy her old marble and sell her a tiny robot. 'How much must I pay? What does it cost? What is the price?' she asked. 'One kind smile,' said the seller. Maya laughed and bought the robot with a grin."],"questions":["What did Maya do before her adventure?","What did she drop?","What was behind the shelf?","How did she pay for the robot?"]}},{"id":"a1-set-22","title":"At the Shop • At the Restaurant • Let's Travel","subtitle":"A1 foundation adventure 22","level":"A1","set":22,"emoji":"🦊","color":"#F6A844","words":[{"term":"cheap","meaning":"رخيص","example":"This pen is cheap.","number":526,"id":"a1:526","level":"A1","lessonId":"a1-set-22"},{"term":"expensive","meaning":"غالي","example":"That phone is expensive.","number":527,"id":"a1:527","level":"A1","lessonId":"a1-set-22"},{"term":"money","meaning":"مال","example":"Save your money.","number":528,"id":"a1:528","level":"A1","lessonId":"a1-set-22"},{"term":"change","meaning":"باقي النقود","example":"Here is your change.","number":529,"id":"a1:529","level":"A1","lessonId":"a1-set-22"},{"term":"receipt","meaning":"إيصال","example":"Keep your receipt.","number":530,"id":"a1:530","level":"A1","lessonId":"a1-set-22"},{"term":"order","meaning":"يطلب","example":"I order a sandwich.","number":531,"id":"a1:531","level":"A1","lessonId":"a1-set-22"},{"term":"menu","meaning":"قائمة الطعام","example":"Read the menu.","number":532,"id":"a1:532","level":"A1","lessonId":"a1-set-22"},{"term":"waiter","meaning":"نادل","example":"The waiter brings water.","number":533,"id":"a1:533","level":"A1","lessonId":"a1-set-22"},{"term":"waitress","meaning":"نادلة","example":"The waitress smiles.","number":534,"id":"a1:534","level":"A1","lessonId":"a1-set-22"},{"term":"customer","meaning":"زبون","example":"The customer pays.","number":535,"id":"a1:535","level":"A1","lessonId":"a1-set-22"},{"term":"bill","meaning":"فاتورة","example":"Can I have the bill?","number":536,"id":"a1:536","level":"A1","lessonId":"a1-set-22"},{"term":"dessert","meaning":"حلوى بعد الطعام","example":"We share a dessert.","number":537,"id":"a1:537","level":"A1","lessonId":"a1-set-22"},{"term":"breakfast","meaning":"فطور","example":"I eat breakfast at seven.","number":538,"id":"a1:538","level":"A1","lessonId":"a1-set-22"},{"term":"lunch","meaning":"غداء","example":"We have lunch at noon.","number":539,"id":"a1:539","level":"A1","lessonId":"a1-set-22"},{"term":"dinner","meaning":"عشاء","example":"Dinner is at six.","number":540,"id":"a1:540","level":"A1","lessonId":"a1-set-22"},{"term":"journey","meaning":"رحلة","example":"The journey is long.","number":541,"id":"a1:541","level":"A1","lessonId":"a1-set-22"},{"term":"trip","meaning":"رحلة قصيرة","example":"We plan a school trip.","number":542,"id":"a1:542","level":"A1","lessonId":"a1-set-22"},{"term":"ticket","meaning":"تذكرة","example":"Here is my ticket.","number":543,"id":"a1:543","level":"A1","lessonId":"a1-set-22"},{"term":"passenger","meaning":"راكب","example":"The passenger is seated.","number":544,"id":"a1:544","level":"A1","lessonId":"a1-set-22"},{"term":"luggage","meaning":"أمتعة","example":"Our luggage is heavy.","number":545,"id":"a1:545","level":"A1","lessonId":"a1-set-22"},{"term":"suitcase","meaning":"حقيبة سفر","example":"My suitcase is blue.","number":546,"id":"a1:546","level":"A1","lessonId":"a1-set-22"},{"term":"passport","meaning":"جواز سفر","example":"I need my passport.","number":547,"id":"a1:547","level":"A1","lessonId":"a1-set-22"},{"term":"hotel","meaning":"فندق","example":"We stay at a hotel.","number":548,"id":"a1:548","level":"A1","lessonId":"a1-set-22"},{"term":"reservation","meaning":"حجز","example":"I have a reservation.","number":549,"id":"a1:549","level":"A1","lessonId":"a1-set-22"},{"term":"tourist","meaning":"سائح","example":"The tourist takes photos.","number":550,"id":"a1:550","level":"A1","lessonId":"a1-set-22"}],"story":{"title":"A Very Strange Holiday Ticket","paragraphs":["At the station shop, Leo saw a cheap notebook and an expensive toy train. He had little money, so he bought the notebook. The cashier gave him his change and a receipt. Then a voice said, 'Please order your lunch before the train leaves!'","At the cafe, Leo opened the menu. A friendly waiter took his order, while a waitress helped another customer. Leo asked for breakfast, but it was already time for lunch. 'I will have soup now and dessert later,' he said. The waiter brought the bill and told him, 'Our dinner begins at six.'","Leo's journey was about to begin. He had planned a short trip with his father. They had a ticket, and each passenger carried luggage. Leo packed a small suitcase and checked his passport. At the hotel, the clerk said, 'We have your reservation.' But a confused tourist was standing beside the wrong door. Leo showed her the map. 'Thank you!' she smiled. 'You have saved my holiday!'"],"questions":["Why did Leo buy the notebook?","What did he eat at the cafe?","What did Leo check before travelling?","Who needed help at the hotel?"]}},{"id":"a1-set-23","title":"At the Hotel • At Work • Jobs","subtitle":"A1 foundation adventure 23","level":"A1","set":23,"emoji":"🦊","color":"#F6A844","words":[{"term":"apartment","meaning":"شقة","example":"Our apartment is on the second floor.","number":551,"id":"a1:551","level":"A1","lessonId":"a1-set-23"},{"term":"elevator","meaning":"مصعد","example":"We take the elevator to our room.","number":552,"id":"a1:552","level":"A1","lessonId":"a1-set-23"},{"term":"reception","meaning":"استقبال","example":"Ask for your room key at reception.","number":553,"id":"a1:553","level":"A1","lessonId":"a1-set-23"},{"term":"guest","meaning":"ضيف","example":"A guest arrives at our home.","number":554,"id":"a1:554","level":"A1","lessonId":"a1-set-23"},{"term":"address","meaning":"عنوان","example":"Write your home address clearly.","number":555,"id":"a1:555","level":"A1","lessonId":"a1-set-23"},{"term":"entrance","meaning":"مدخل","example":"Meet us at the main entrance.","number":556,"id":"a1:556","level":"A1","lessonId":"a1-set-23"},{"term":"exit","meaning":"مخرج","example":"Follow the signs to the exit.","number":557,"id":"a1:557","level":"A1","lessonId":"a1-set-23"},{"term":"lobby","meaning":"ردهة","example":"We wait in the hotel lobby.","number":558,"id":"a1:558","level":"A1","lessonId":"a1-set-23"},{"term":"corridor","meaning":"ممر داخلي","example":"Walk quietly through the corridor.","number":559,"id":"a1:559","level":"A1","lessonId":"a1-set-23"},{"term":"upstairs","meaning":"الطابق العلوي","example":"My room is upstairs.","number":560,"id":"a1:560","level":"A1","lessonId":"a1-set-23"},{"term":"office","meaning":"مكتب","example":"My mother works in an office.","number":561,"id":"a1:561","level":"A1","lessonId":"a1-set-23"},{"term":"job","meaning":"وظيفة","example":"My father has a job.","number":562,"id":"a1:562","level":"A1","lessonId":"a1-set-23"},{"term":"worker","meaning":"عامل","example":"The worker is busy.","number":563,"id":"a1:563","level":"A1","lessonId":"a1-set-23"},{"term":"manager","meaning":"مدير","example":"The manager is here.","number":564,"id":"a1:564","level":"A1","lessonId":"a1-set-23"},{"term":"boss","meaning":"رئيس العمل","example":"My boss is friendly.","number":565,"id":"a1:565","level":"A1","lessonId":"a1-set-23"},{"term":"company","meaning":"شركة","example":"The company is large.","number":566,"id":"a1:566","level":"A1","lessonId":"a1-set-23"},{"term":"meeting","meaning":"اجتماع","example":"The meeting starts now.","number":567,"id":"a1:567","level":"A1","lessonId":"a1-set-23"},{"term":"team","meaning":"فريق","example":"Our team works together.","number":568,"id":"a1:568","level":"A1","lessonId":"a1-set-23"},{"term":"colleague","meaning":"زميل عمل","example":"A colleague helps me.","number":569,"id":"a1:569","level":"A1","lessonId":"a1-set-23"},{"term":"salary","meaning":"راتب","example":"He saves his salary.","number":570,"id":"a1:570","level":"A1","lessonId":"a1-set-23"},{"term":"doctor","meaning":"طبيب","example":"The doctor checks my temperature.","number":571,"id":"a1:571","level":"A1","lessonId":"a1-set-23"},{"term":"nurse","meaning":"ممرضة","example":"A nurse helps patients feel better.","number":572,"id":"a1:572","level":"A1","lessonId":"a1-set-23"},{"term":"dentist","meaning":"طبيب أسنان","example":"The dentist checks my teeth.","number":573,"id":"a1:573","level":"A1","lessonId":"a1-set-23"},{"term":"engineer","meaning":"مهندس","example":"An engineer designs a strong bridge.","number":574,"id":"a1:574","level":"A1","lessonId":"a1-set-23"},{"term":"farmer","meaning":"مزارع","example":"The farmer grows carrots and corn.","number":575,"id":"a1:575","level":"A1","lessonId":"a1-set-23"}],"story":{"title":"The Elevator to Everywhere","paragraphs":["Nina's family stayed in an apartment above a busy hotel. At reception, a guest asked for the address. Nina pointed to the entrance, then the exit, and showed him the lobby. 'The elevator is over there, past the corridor. You can also walk upstairs,' she explained.","The elevator opened on a strange floor. Instead of a bedroom, Nina saw an office! A worker was doing a job at a desk. A manager spoke to the boss of a company. 'Our team is having a meeting,' said a colleague. 'We are discussing our salary and a new project.' Nina blinked. 'This is not my hotel room!'","The doors opened again. On the next floor, a doctor and nurse were talking to a dentist. An engineer was drawing a machine, while a farmer carried a basket of apples. Everyone looked surprised to see Nina. She pressed the button for the ground floor. At last she reached the lobby. 'Next time,' she said, 'I'll use the stairs!'"],"questions":["Where was Nina staying?","What was on the first strange floor?","Name two people on the next floor.","What did Nina decide to use next time?"]}},{"id":"a1-set-24","title":"Jobs • At the Doctor • The Human Body","subtitle":"A1 foundation adventure 24","level":"A1","set":24,"emoji":"🦊","color":"#F6A844","words":[{"term":"pilot","meaning":"طيار","example":"The pilot flies a passenger plane.","number":576,"id":"a1:576","level":"A1","lessonId":"a1-set-24"},{"term":"driver","meaning":"سائق","example":"The bus driver waits for everyone.","number":577,"id":"a1:577","level":"A1","lessonId":"a1-set-24"},{"term":"singer","meaning":"مغن","example":"The singer holds a microphone.","number":578,"id":"a1:578","level":"A1","lessonId":"a1-set-24"},{"term":"actor","meaning":"ممثل","example":"The actor plays a funny character.","number":579,"id":"a1:579","level":"A1","lessonId":"a1-set-24"},{"term":"artist","meaning":"فنان","example":"The artist draws colorful pictures.","number":580,"id":"a1:580","level":"A1","lessonId":"a1-set-24"},{"term":"ill","meaning":"مريض","example":"I feel ill today.","number":581,"id":"a1:581","level":"A1","lessonId":"a1-set-24"},{"term":"sick","meaning":"مريض","example":"The boy is sick.","number":582,"id":"a1:582","level":"A1","lessonId":"a1-set-24"},{"term":"healthy","meaning":"صحي","example":"Fruit is healthy.","number":583,"id":"a1:583","level":"A1","lessonId":"a1-set-24"},{"term":"pain","meaning":"ألم","example":"I have pain in my leg.","number":584,"id":"a1:584","level":"A1","lessonId":"a1-set-24"},{"term":"headache","meaning":"صداع","example":"I have a headache.","number":585,"id":"a1:585","level":"A1","lessonId":"a1-set-24"},{"term":"fever","meaning":"حمى","example":"He has a fever.","number":586,"id":"a1:586","level":"A1","lessonId":"a1-set-24"},{"term":"cough","meaning":"سعال","example":"She has a cough.","number":587,"id":"a1:587","level":"A1","lessonId":"a1-set-24"},{"term":"medicine","meaning":"دواء","example":"Take your medicine.","number":588,"id":"a1:588","level":"A1","lessonId":"a1-set-24"},{"term":"injury","meaning":"إصابة","example":"The player has an injury.","number":589,"id":"a1:589","level":"A1","lessonId":"a1-set-24"},{"term":"appointment","meaning":"موعد","example":"I have an appointment.","number":590,"id":"a1:590","level":"A1","lessonId":"a1-set-24"},{"term":"shoulder","meaning":"كتف","example":"My backpack rests on my shoulder.","number":591,"id":"a1:591","level":"A1","lessonId":"a1-set-24"},{"term":"elbow","meaning":"مرفق","example":"Bend your elbow to lift your hand.","number":592,"id":"a1:592","level":"A1","lessonId":"a1-set-24"},{"term":"wrist","meaning":"رسغ","example":"I wear a watch on my wrist.","number":593,"id":"a1:593","level":"A1","lessonId":"a1-set-24"},{"term":"ankle","meaning":"كاحل","example":"The runner twists an ankle.","number":594,"id":"a1:594","level":"A1","lessonId":"a1-set-24"},{"term":"neck","meaning":"رقبة","example":"I wrap a scarf around my neck.","number":595,"id":"a1:595","level":"A1","lessonId":"a1-set-24"},{"term":"chest","meaning":"صدر","example":"The doctor listens to my chest.","number":596,"id":"a1:596","level":"A1","lessonId":"a1-set-24"},{"term":"brain","meaning":"دماغ","example":"Our brain helps us think.","number":597,"id":"a1:597","level":"A1","lessonId":"a1-set-24"},{"term":"skin","meaning":"جلد","example":"Use soap to keep your skin clean.","number":598,"id":"a1:598","level":"A1","lessonId":"a1-set-24"},{"term":"blood","meaning":"دم","example":"Blood carries oxygen.","number":599,"id":"a1:599","level":"A1","lessonId":"a1-set-24"},{"term":"bone","meaning":"عظم","example":"A strong bone supports the body.","number":600,"id":"a1:600","level":"A1","lessonId":"a1-set-24"}],"story":{"title":"The Silly Superhero Checkup","paragraphs":["The town's new superhero club met every Friday. A pilot, a driver, a singer, an actor, and an artist all wore funny capes. One day the pilot said, 'I feel ill.' The driver felt sick, too. 'We must stay healthy,' said the singer. 'Let's visit the clinic.'","At the clinic, a nurse asked, 'Where is the pain?' The pilot had a headache, the driver had a fever, and the actor had a little cough. The artist had a small injury on his hand. The nurse gave simple advice, and the doctor explained how to use medicine safely. 'Please make an appointment if you still feel unwell,' she said.","The doctor asked everyone to point to a shoulder, elbow, wrist, ankle, neck, and chest. 'Our brain helps us think, our skin protects us, our blood moves through the body, and every bone supports us,' she explained. The heroes listened carefully. When they felt better, they promised to rest before their next adventure."],"questions":["Who felt ill first?","What did the actor have?","What did the doctor tell the heroes to do?","What helps the body stand?"]}},{"id":"a1-set-25","title":"Housework • Around the World • Our Planet","subtitle":"A1 foundation adventure 25","level":"A1","set":25,"emoji":"🦊","color":"#F6A844","words":[{"term":"sweep","meaning":"يكنس","example":"I sweep the floor.","number":601,"id":"a1:601","level":"A1","lessonId":"a1-set-25"},{"term":"mop","meaning":"يمسح الأرض","example":"We mop the floor.","number":602,"id":"a1:602","level":"A1","lessonId":"a1-set-25"},{"term":"dust","meaning":"ينفض الغبار","example":"I dust the shelves.","number":603,"id":"a1:603","level":"A1","lessonId":"a1-set-25"},{"term":"vacuum","meaning":"ينظف بالمكنسة","example":"I vacuum the carpet.","number":604,"id":"a1:604","level":"A1","lessonId":"a1-set-25"},{"term":"iron","meaning":"يكوي","example":"I iron my shirt.","number":605,"id":"a1:605","level":"A1","lessonId":"a1-set-25"},{"term":"fold","meaning":"يطوي","example":"Please fold the clothes.","number":606,"id":"a1:606","level":"A1","lessonId":"a1-set-25"},{"term":"repair","meaning":"يصلح","example":"We repair the bicycle.","number":607,"id":"a1:607","level":"A1","lessonId":"a1-set-25"},{"term":"fix","meaning":"يصلح","example":"Can you fix the chair?","number":608,"id":"a1:608","level":"A1","lessonId":"a1-set-25"},{"term":"rubbish","meaning":"قمامة","example":"Put rubbish in the bin.","number":609,"id":"a1:609","level":"A1","lessonId":"a1-set-25"},{"term":"laundry","meaning":"غسيل","example":"The laundry is clean.","number":610,"id":"a1:610","level":"A1","lessonId":"a1-set-25"},{"term":"forest","meaning":"غابة","example":"Many birds live in the forest.","number":611,"id":"a1:611","level":"A1","lessonId":"a1-set-25"},{"term":"desert","meaning":"صحراء","example":"A camel walks across the desert.","number":612,"id":"a1:612","level":"A1","lessonId":"a1-set-25"},{"term":"island","meaning":"جزيرة","example":"An island has water all around it.","number":613,"id":"a1:613","level":"A1","lessonId":"a1-set-25"},{"term":"beach","meaning":"شاطئ","example":"We build sandcastles on the beach.","number":614,"id":"a1:614","level":"A1","lessonId":"a1-set-25"},{"term":"ocean","meaning":"محيط","example":"A whale swims in the ocean.","number":615,"id":"a1:615","level":"A1","lessonId":"a1-set-25"},{"term":"waterfall","meaning":"شلال","example":"Water falls over rocks at a waterfall.","number":616,"id":"a1:616","level":"A1","lessonId":"a1-set-25"},{"term":"valley","meaning":"واد","example":"A valley lies between two mountains.","number":617,"id":"a1:617","level":"A1","lessonId":"a1-set-25"},{"term":"hill","meaning":"تل","example":"We run down the grassy hill.","number":618,"id":"a1:618","level":"A1","lessonId":"a1-set-25"},{"term":"field","meaning":"حقل","example":"The cows eat grass in the field.","number":619,"id":"a1:619","level":"A1","lessonId":"a1-set-25"},{"term":"countryside","meaning":"ريف","example":"The countryside has farms and fields.","number":620,"id":"a1:620","level":"A1","lessonId":"a1-set-25"},{"term":"earth","meaning":"الأرض","example":"We live on Earth.","number":621,"id":"a1:621","level":"A1","lessonId":"a1-set-25"},{"term":"world","meaning":"العالم","example":"The world is big.","number":622,"id":"a1:622","level":"A1","lessonId":"a1-set-25"},{"term":"planet","meaning":"كوكب","example":"Earth is a planet.","number":623,"id":"a1:623","level":"A1","lessonId":"a1-set-25"},{"term":"nature","meaning":"طبيعة","example":"We love nature.","number":624,"id":"a1:624","level":"A1","lessonId":"a1-set-25"},{"term":"environment","meaning":"بيئة","example":"Protect the environment.","number":625,"id":"a1:625","level":"A1","lessonId":"a1-set-25"}],"story":{"title":"The Cleaning Robot’s World Tour","paragraphs":["A clever little robot was made to help with housework. It could sweep the floor, mop the kitchen, dust the shelves, and vacuum the carpet. It even learned to iron a shirt and fold the laundry. But when it tried to repair a chair, it made things worse. 'I will fix it later,' said the robot, putting the rubbish outside.","One day it found a magical map. The map showed a forest, a desert, an island, and a sunny beach. Beyond them were an ocean, a waterfall, a valley, a hill, and a green field in the countryside. 'I want to see the whole earth!' cried the robot. It packed a tiny bag and began its trip around the world.","As it traveled, the robot noticed how beautiful the planet was. It saw birds, mountains, rivers, and clean skies. 'Nature is our home,' it said. 'We must protect the environment.' It returned to its family and helped clean the park. Everyone agreed that this was its best job yet."],"questions":["What was the robot made to do?","What did it find?","Where did the map lead it?","What did the robot want to protect?"]}},{"id":"a1-set-26","title":"Our Planet • Science Lab • More Amazing Animals","subtitle":"A1 foundation adventure 26","level":"A1","set":26,"emoji":"🦊","color":"#F6A844","words":[{"term":"recycle","meaning":"يعيد التدوير","example":"We recycle paper.","number":626,"id":"a1:626","level":"A1","lessonId":"a1-set-26"},{"term":"waste","meaning":"نفايات","example":"Do not waste water.","number":627,"id":"a1:627","level":"A1","lessonId":"a1-set-26"},{"term":"pollution","meaning":"تلوث","example":"Pollution harms animals.","number":628,"id":"a1:628","level":"A1","lessonId":"a1-set-26"},{"term":"plastic","meaning":"بلاستيك","example":"This bottle is plastic.","number":629,"id":"a1:629","level":"A1","lessonId":"a1-set-26"},{"term":"energy","meaning":"طاقة","example":"The sun gives us energy.","number":630,"id":"a1:630","level":"A1","lessonId":"a1-set-26"},{"term":"magnet","meaning":"مغناطيس","example":"A magnet attracts metal.","number":631,"id":"a1:631","level":"A1","lessonId":"a1-set-26"},{"term":"experiment","meaning":"تجربة","example":"We try an experiment.","number":632,"id":"a1:632","level":"A1","lessonId":"a1-set-26"},{"term":"temperature","meaning":"درجة الحرارة","example":"The temperature is high.","number":633,"id":"a1:633","level":"A1","lessonId":"a1-set-26"},{"term":"science","meaning":"علوم","example":"We enjoy science.","number":634,"id":"a1:634","level":"A1","lessonId":"a1-set-26"},{"term":"machine","meaning":"آلة","example":"This machine is useful.","number":635,"id":"a1:635","level":"A1","lessonId":"a1-set-26"},{"term":"tool","meaning":"أداة","example":"This tool is strong.","number":636,"id":"a1:636","level":"A1","lessonId":"a1-set-26"},{"term":"battery","meaning":"بطارية","example":"The clock needs a battery.","number":637,"id":"a1:637","level":"A1","lessonId":"a1-set-26"},{"term":"metal","meaning":"معدن","example":"The spoon is metal.","number":638,"id":"a1:638","level":"A1","lessonId":"a1-set-26"},{"term":"wood","meaning":"خشب","example":"The table is made of wood.","number":639,"id":"a1:639","level":"A1","lessonId":"a1-set-26"},{"term":"material","meaning":"مادة","example":"Cotton is a material.","number":640,"id":"a1:640","level":"A1","lessonId":"a1-set-26"},{"term":"whale","meaning":"حوت","example":"A whale breathes air above the water.","number":641,"id":"a1:641","level":"A1","lessonId":"a1-set-26"},{"term":"dolphin","meaning":"دلفين","example":"A dolphin can jump out of the sea.","number":642,"id":"a1:642","level":"A1","lessonId":"a1-set-26"},{"term":"shark","meaning":"قرش","example":"A shark has rows of sharp teeth.","number":643,"id":"a1:643","level":"A1","lessonId":"a1-set-26"},{"term":"penguin","meaning":"بطريق","example":"A penguin swims but cannot fly.","number":644,"id":"a1:644","level":"A1","lessonId":"a1-set-26"},{"term":"kangaroo","meaning":"كنغر","example":"A kangaroo carries its baby in a pouch.","number":645,"id":"a1:645","level":"A1","lessonId":"a1-set-26"},{"term":"camel","meaning":"جمل","example":"A camel can walk far in the desert.","number":646,"id":"a1:646","level":"A1","lessonId":"a1-set-26"},{"term":"fox","meaning":"ثعلب","example":"A clever fox hides near a tree.","number":647,"id":"a1:647","level":"A1","lessonId":"a1-set-26"},{"term":"deer","meaning":"غزال","example":"A deer runs quickly through the forest.","number":648,"id":"a1:648","level":"A1","lessonId":"a1-set-26"},{"term":"wolf","meaning":"ذئب","example":"A wolf howls at night.","number":649,"id":"a1:649","level":"A1","lessonId":"a1-set-26"},{"term":"owl","meaning":"بومة","example":"An owl has large round eyes.","number":650,"id":"a1:650","level":"A1","lessonId":"a1-set-26"}],"story":{"title":"The Green Science Detective","paragraphs":["At Green School, the science club had one rule: recycle what you can. 'Less waste means less pollution,' said Dr. Lee. She showed the class a plastic bottle and asked, 'How can we turn this into something useful?' Mia suggested a windmill that could make energy.","They began an experiment. On the table were a magnet, a small machine, a tool, a battery, a piece of metal, a block of wood, and another material that looked like glass. Dr. Lee checked the temperature and wrote the results on the board. 'Science is like solving a mystery,' she said.","Then the class visited a wildlife center. They learned about the whale, dolphin, shark, penguin, kangaroo, camel, fox, deer, wolf, and owl. The children noticed that every animal needed a safe home. 'Now I understand our experiment,' said Mia. 'We can build things without hurting the animals!' They made a little windmill from old bottles, and it spun beautifully."],"questions":["What was the school's special rule?","What did the children try to build?","Where did the class go?","Why did they reuse old bottles?"]}},{"id":"a1-set-27","title":"Let's Cook • More Food • School Progress","subtitle":"A1 foundation adventure 27","level":"A1","set":27,"emoji":"🦊","color":"#F6A844","words":[{"term":"bake","meaning":"يخبز","example":"We bake bread.","number":651,"id":"a1:651","level":"A1","lessonId":"a1-set-27"},{"term":"boil","meaning":"يغلي","example":"Boil the water.","number":652,"id":"a1:652","level":"A1","lessonId":"a1-set-27"},{"term":"fry","meaning":"يقلي","example":"We fry the eggs.","number":653,"id":"a1:653","level":"A1","lessonId":"a1-set-27"},{"term":"roast","meaning":"يشوي","example":"We roast the chicken.","number":654,"id":"a1:654","level":"A1","lessonId":"a1-set-27"},{"term":"slice","meaning":"يقطع شرائح","example":"Slice the apple.","number":655,"id":"a1:655","level":"A1","lessonId":"a1-set-27"},{"term":"mix","meaning":"يمزج","example":"Mix the flour and water.","number":656,"id":"a1:656","level":"A1","lessonId":"a1-set-27"},{"term":"pour","meaning":"يسكب","example":"Pour the juice.","number":657,"id":"a1:657","level":"A1","lessonId":"a1-set-27"},{"term":"taste","meaning":"يتذوق","example":"Taste the soup.","number":658,"id":"a1:658","level":"A1","lessonId":"a1-set-27"},{"term":"smell","meaning":"يشم","example":"I smell fresh bread.","number":659,"id":"a1:659","level":"A1","lessonId":"a1-set-27"},{"term":"recipe","meaning":"وصفة طعام","example":"Read the recipe.","number":660,"id":"a1:660","level":"A1","lessonId":"a1-set-27"},{"term":"pineapple","meaning":"أناناس","example":"A pineapple has a rough skin.","number":661,"id":"a1:661","level":"A1","lessonId":"a1-set-27"},{"term":"melon","meaning":"شمام","example":"We share a sweet melon after lunch.","number":662,"id":"a1:662","level":"A1","lessonId":"a1-set-27"},{"term":"coconut","meaning":"جوز الهند","example":"The coconut is hard.","number":663,"id":"a1:663","level":"A1","lessonId":"a1-set-27"},{"term":"kiwi","meaning":"كيوي","example":"A kiwi is green inside.","number":664,"id":"a1:664","level":"A1","lessonId":"a1-set-27"},{"term":"plum","meaning":"برقوق","example":"This plum is small and purple.","number":665,"id":"a1:665","level":"A1","lessonId":"a1-set-27"},{"term":"raspberry","meaning":"توت العليق","example":"I put a raspberry on my cake.","number":666,"id":"a1:666","level":"A1","lessonId":"a1-set-27"},{"term":"mushroom","meaning":"فطر","example":"I see a mushroom.","number":667,"id":"a1:667","level":"A1","lessonId":"a1-set-27"},{"term":"bean","meaning":"حبة فاصولياء","example":"We grow a bean in a cup of soil.","number":668,"id":"a1:668","level":"A1","lessonId":"a1-set-27"},{"term":"pea","meaning":"حبة بازلاء","example":"A green pea rolls off the plate.","number":669,"id":"a1:669","level":"A1","lessonId":"a1-set-27"},{"term":"spinach","meaning":"سبانخ","example":"Spinach is green.","number":670,"id":"a1:670","level":"A1","lessonId":"a1-set-27"},{"term":"homework","meaning":"واجب منزلي","example":"I do my homework.","number":671,"id":"a1:671","level":"A1","lessonId":"a1-set-27"},{"term":"lesson","meaning":"درس","example":"The lesson is fun.","number":672,"id":"a1:672","level":"A1","lessonId":"a1-set-27"},{"term":"subject","meaning":"مادة دراسية","example":"English is my favorite subject.","number":673,"id":"a1:673","level":"A1","lessonId":"a1-set-27"},{"term":"exercise","meaning":"تمرين","example":"Try this exercise.","number":674,"id":"a1:674","level":"A1","lessonId":"a1-set-27"},{"term":"test","meaning":"اختبار","example":"We have a short test.","number":675,"id":"a1:675","level":"A1","lessonId":"a1-set-27"}],"story":{"title":"Chef Mia’s Homework Surprise","paragraphs":["Mia's class had a cooking challenge. 'You may bake, boil, fry, or roast,' said the teacher, 'but ask an adult for help with hot things.' Mia decided to make a fruit dish. First she had to slice the fruit, mix it gently, and pour a little juice over it. She wanted to taste it, but the wonderful smell made her hungry. 'Follow the recipe,' her father reminded her.","On the table were pineapple, melon, coconut, kiwi, plum, and raspberry. From the garden they picked a mushroom, a bean, a pea, and some spinach for a vegetable side dish. 'This looks like a rainbow!' Mia said.","At school, she brought her homework to the lesson. The class's subject was food and health. During the exercise, everyone described a dish. Mia's fruit salad became the star of the test. Her teacher smiled. 'You followed the instructions, worked safely, and made a delicious meal.' Mia took a happy bow."],"questions":["What dish did Mia choose to make?","Who reminded her to follow the recipe?","Where did they get the vegetables?","What did the teacher praise?"]}},{"id":"a1-set-28","title":"School Progress • Language Skills • Stories and Books","subtitle":"A1 foundation adventure 28","level":"A1","set":28,"emoji":"🦊","color":"#F6A844","words":[{"term":"exam","meaning":"امتحان","example":"The exam is tomorrow.","number":676,"id":"a1:676","level":"A1","lessonId":"a1-set-28"},{"term":"project","meaning":"مشروع","example":"Our project is about space.","number":677,"id":"a1:677","level":"A1","lessonId":"a1-set-28"},{"term":"question","meaning":"سؤال","example":"Ask a question.","number":678,"id":"a1:678","level":"A1","lessonId":"a1-set-28"},{"term":"result","meaning":"نتيجة","example":"I am happy with my result.","number":679,"id":"a1:679","level":"A1","lessonId":"a1-set-28"},{"term":"grade","meaning":"درجة دراسية","example":"My grade is good.","number":680,"id":"a1:680","level":"A1","lessonId":"a1-set-28"},{"term":"language","meaning":"لغة","example":"English is a language.","number":681,"id":"a1:681","level":"A1","lessonId":"a1-set-28"},{"term":"word","meaning":"كلمة","example":"Learn one new word.","number":682,"id":"a1:682","level":"A1","lessonId":"a1-set-28"},{"term":"sentence","meaning":"جملة","example":"Write a sentence.","number":683,"id":"a1:683","level":"A1","lessonId":"a1-set-28"},{"term":"paragraph","meaning":"فقرة","example":"Read the paragraph.","number":684,"id":"a1:684","level":"A1","lessonId":"a1-set-28"},{"term":"letter","meaning":"حرف","example":"A is a letter.","number":685,"id":"a1:685","level":"A1","lessonId":"a1-set-28"},{"term":"sound","meaning":"صوت","example":"Listen to this sound.","number":686,"id":"a1:686","level":"A1","lessonId":"a1-set-28"},{"term":"syllable","meaning":"مقطع صوتي","example":"Clap each syllable.","number":687,"id":"a1:687","level":"A1","lessonId":"a1-set-28"},{"term":"meaning","meaning":"معنى","example":"What is the meaning?","number":688,"id":"a1:688","level":"A1","lessonId":"a1-set-28"},{"term":"translate","meaning":"يترجم","example":"Please translate this word.","number":689,"id":"a1:689","level":"A1","lessonId":"a1-set-28"},{"term":"grammar","meaning":"قواعد اللغة","example":"We practice grammar.","number":690,"id":"a1:690","level":"A1","lessonId":"a1-set-28"},{"term":"story","meaning":"قصة","example":"Tell me a funny story.","number":691,"id":"a1:691","level":"A1","lessonId":"a1-set-28"},{"term":"chapter","meaning":"فصل في كتاب","example":"Read the next chapter.","number":692,"id":"a1:692","level":"A1","lessonId":"a1-set-28"},{"term":"title","meaning":"عنوان","example":"Write a title for your story.","number":693,"id":"a1:693","level":"A1","lessonId":"a1-set-28"},{"term":"author","meaning":"مؤلف","example":"The author wrote a book.","number":694,"id":"a1:694","level":"A1","lessonId":"a1-set-28"},{"term":"character","meaning":"شخصية","example":"The main character is brave.","number":695,"id":"a1:695","level":"A1","lessonId":"a1-set-28"},{"term":"adventure","meaning":"مغامرة","example":"We read an exciting adventure.","number":696,"id":"a1:696","level":"A1","lessonId":"a1-set-28"},{"term":"mystery","meaning":"لغز","example":"The children solve a mystery.","number":697,"id":"a1:697","level":"A1","lessonId":"a1-set-28"},{"term":"ending","meaning":"نهاية","example":"The ending makes us smile.","number":698,"id":"a1:698","level":"A1","lessonId":"a1-set-28"},{"term":"beginning","meaning":"بداية","example":"Read the beginning first.","number":699,"id":"a1:699","level":"A1","lessonId":"a1-set-28"},{"term":"fiction","meaning":"قصة خيالية","example":"I like reading fiction.","number":700,"id":"a1:700","level":"A1","lessonId":"a1-set-28"}],"story":{"title":"The Book That Wrote Back","paragraphs":["Nina was worried about her English exam. She had a big project and a tricky question, and she hoped for a good result and grade. At the library she found a strange book. 'I can help with language,' it whispered. 'Start with a word, then make a sentence, then a paragraph.'","'What about a letter?' asked Nina. The book made a funny sound. 'Every syllable has a beat, and every word has a meaning,' it said. 'You can translate a difficult idea, but remember your grammar.' The pages suddenly began to turn by themselves.","A new story appeared. In its first chapter was a title: 'The Lost Author.' Its main character was a brave girl on an adventure. She wanted to solve a mystery, but the ending was missing! 'Let's write the beginning clearly,' said Nina, 'and then invent the last page.' The book laughed. 'Now you understand fiction. Stories grow when you use your imagination.' Nina returned to class feeling ready for her exam."],"questions":["Why was Nina worried?","What could the strange book do?","What was missing from the story?","How did Nina feel afterward?"]}},{"id":"a1-set-29","title":"Math Time • Measuring Things • Good Character","subtitle":"A1 foundation adventure 29","level":"A1","set":29,"emoji":"🦊","color":"#F6A844","words":[{"term":"add","meaning":"يجمع","example":"Add two and three.","number":701,"id":"a1:701","level":"A1","lessonId":"a1-set-29"},{"term":"subtract","meaning":"يطرح","example":"Subtract one from five.","number":702,"id":"a1:702","level":"A1","lessonId":"a1-set-29"},{"term":"multiply","meaning":"يضرب","example":"Multiply two by three.","number":703,"id":"a1:703","level":"A1","lessonId":"a1-set-29"},{"term":"divide","meaning":"يقسم","example":"Divide ten by two.","number":704,"id":"a1:704","level":"A1","lessonId":"a1-set-29"},{"term":"total","meaning":"مجموع","example":"The total is twelve.","number":705,"id":"a1:705","level":"A1","lessonId":"a1-set-29"},{"term":"equal","meaning":"مساو","example":"Two plus two is equal to four.","number":706,"id":"a1:706","level":"A1","lessonId":"a1-set-29"},{"term":"half","meaning":"نصف","example":"Eat half the apple.","number":707,"id":"a1:707","level":"A1","lessonId":"a1-set-29"},{"term":"quarter","meaning":"ربع","example":"A quarter is one fourth.","number":708,"id":"a1:708","level":"A1","lessonId":"a1-set-29"},{"term":"double","meaning":"ضعف","example":"Double four is eight.","number":709,"id":"a1:709","level":"A1","lessonId":"a1-set-29"},{"term":"sum","meaning":"ناتج الجمع","example":"The sum is seven.","number":710,"id":"a1:710","level":"A1","lessonId":"a1-set-29"},{"term":"height","meaning":"ارتفاع","example":"Measure the height.","number":711,"id":"a1:711","level":"A1","lessonId":"a1-set-29"},{"term":"length","meaning":"طول","example":"Check the length.","number":712,"id":"a1:712","level":"A1","lessonId":"a1-set-29"},{"term":"weight","meaning":"وزن","example":"The weight is five kilos.","number":713,"id":"a1:713","level":"A1","lessonId":"a1-set-29"},{"term":"size","meaning":"حجم","example":"What size is this?","number":714,"id":"a1:714","level":"A1","lessonId":"a1-set-29"},{"term":"shape","meaning":"شكل","example":"A circle is a shape.","number":715,"id":"a1:715","level":"A1","lessonId":"a1-set-29"},{"term":"distance","meaning":"مسافة","example":"The distance is short.","number":716,"id":"a1:716","level":"A1","lessonId":"a1-set-29"},{"term":"speed","meaning":"سرعة","example":"The car has a high speed.","number":717,"id":"a1:717","level":"A1","lessonId":"a1-set-29"},{"term":"level","meaning":"مستوى","example":"This is level one.","number":718,"id":"a1:718","level":"A1","lessonId":"a1-set-29"},{"term":"amount","meaning":"كمية","example":"Use a small amount.","number":719,"id":"a1:719","level":"A1","lessonId":"a1-set-29"},{"term":"measure","meaning":"يقيس","example":"Measure the table.","number":720,"id":"a1:720","level":"A1","lessonId":"a1-set-29"},{"term":"kind","meaning":"لطيف","example":"The teacher is kind.","number":721,"id":"a1:721","level":"A1","lessonId":"a1-set-29"},{"term":"polite","meaning":"مهذب","example":"The student is polite.","number":722,"id":"a1:722","level":"A1","lessonId":"a1-set-29"},{"term":"rude","meaning":"وقح","example":"The boy is rude.","number":723,"id":"a1:723","level":"A1","lessonId":"a1-set-29"},{"term":"honest","meaning":"صادق","example":"The friend is honest.","number":724,"id":"a1:724","level":"A1","lessonId":"a1-set-29"},{"term":"brave","meaning":"شجاع","example":"The firefighter is brave.","number":725,"id":"a1:725","level":"A1","lessonId":"a1-set-29"}],"story":{"title":"The Brave Bridge Builders","paragraphs":["Two friends wanted to build a bridge for their toy cars. 'First, add these blocks,' said Ben. 'Now subtract two. If we multiply the rows, we can make the bridge longer.' Zoe laughed. 'We should divide the work equally. The total must be equal on both sides. Half the blocks are yours, and a quarter of the box is mine. If we double our effort, the sum will be perfect!'","They checked the height, length, weight, and size of every part. 'A strong shape matters,' said Zoe. They measured the distance across the gap and tested the speed of a toy car. They used a ruler to find the level of the road and decided what amount of glue to use. 'Always measure twice,' Ben reminded her.","Just then, a rude boy laughed at their work. A kind girl gave them more blocks. Zoe was polite and thanked her. Ben was honest: 'We need to try again.' They stayed brave, fixed the bridge, and watched the first car cross safely. Everyone cheered."],"questions":["What were the friends building?","What did they measure?","Who helped them?","What happened at the end?"]}},{"id":"a1-set-30","title":"Good Character • More Feelings • Comparing","subtitle":"A1 foundation adventure 30","level":"A1","set":30,"emoji":"🦊","color":"#F6A844","words":[{"term":"shy","meaning":"خجول","example":"The child is shy.","number":726,"id":"a1:726","level":"A1","lessonId":"a1-set-30"},{"term":"friendly","meaning":"ودود","example":"The dog is friendly.","number":727,"id":"a1:727","level":"A1","lessonId":"a1-set-30"},{"term":"clever","meaning":"ذكي","example":"The girl is clever.","number":728,"id":"a1:728","level":"A1","lessonId":"a1-set-30"},{"term":"lazy","meaning":"كسول","example":"The cat is lazy.","number":729,"id":"a1:729","level":"A1","lessonId":"a1-set-30"},{"term":"serious","meaning":"جدي","example":"The man is serious.","number":730,"id":"a1:730","level":"A1","lessonId":"a1-set-30"},{"term":"worried","meaning":"قلق","example":"I feel worried today.","number":731,"id":"a1:731","level":"A1","lessonId":"a1-set-30"},{"term":"nervous","meaning":"متوتر","example":"I feel nervous today.","number":732,"id":"a1:732","level":"A1","lessonId":"a1-set-30"},{"term":"proud","meaning":"فخور","example":"I feel proud today.","number":733,"id":"a1:733","level":"A1","lessonId":"a1-set-30"},{"term":"calm","meaning":"هادئ","example":"I feel calm today.","number":734,"id":"a1:734","level":"A1","lessonId":"a1-set-30"},{"term":"lonely","meaning":"وحيد","example":"I feel lonely today.","number":735,"id":"a1:735","level":"A1","lessonId":"a1-set-30"},{"term":"jealous","meaning":"غيور","example":"I feel jealous today.","number":736,"id":"a1:736","level":"A1","lessonId":"a1-set-30"},{"term":"disappointed","meaning":"خائب الأمل","example":"I feel disappointed today.","number":737,"id":"a1:737","level":"A1","lessonId":"a1-set-30"},{"term":"confused","meaning":"مرتبك","example":"I feel confused today.","number":738,"id":"a1:738","level":"A1","lessonId":"a1-set-30"},{"term":"grateful","meaning":"ممتن","example":"I feel grateful today.","number":739,"id":"a1:739","level":"A1","lessonId":"a1-set-30"},{"term":"confident","meaning":"واثق","example":"I feel confident today.","number":740,"id":"a1:740","level":"A1","lessonId":"a1-set-30"},{"term":"better","meaning":"أفضل","example":"This book is better.","number":741,"id":"a1:741","level":"A1","lessonId":"a1-set-30"},{"term":"worse","meaning":"أسوأ","example":"The weather is worse.","number":742,"id":"a1:742","level":"A1","lessonId":"a1-set-30"},{"term":"best","meaning":"الأفضل","example":"This is my best work.","number":743,"id":"a1:743","level":"A1","lessonId":"a1-set-30"},{"term":"worst","meaning":"الأسوأ","example":"That was my worst day.","number":744,"id":"a1:744","level":"A1","lessonId":"a1-set-30"},{"term":"higher","meaning":"أعلى","example":"The bird flies higher.","number":745,"id":"a1:745","level":"A1","lessonId":"a1-set-30"},{"term":"lower","meaning":"أقل ارتفاعا","example":"Put the box lower.","number":746,"id":"a1:746","level":"A1","lessonId":"a1-set-30"},{"term":"faster","meaning":"أسرع","example":"A car is faster than a bike.","number":747,"id":"a1:747","level":"A1","lessonId":"a1-set-30"},{"term":"slower","meaning":"أبطأ","example":"A snail is slower.","number":748,"id":"a1:748","level":"A1","lessonId":"a1-set-30"},{"term":"stronger","meaning":"أقوى","example":"The horse is stronger.","number":749,"id":"a1:749","level":"A1","lessonId":"a1-set-30"},{"term":"weaker","meaning":"أضعف","example":"The kitten is weaker.","number":750,"id":"a1:750","level":"A1","lessonId":"a1-set-30"}],"story":{"title":"The Hill Race of Feelings","paragraphs":["At the school race, Tom was shy, but his sister was friendly and clever. Their cousin was lazy about training, while the coach looked serious. The runners were worried and nervous before the start. Tom felt lonely when no one stood beside him, and he was jealous of the fastest runner. 'Stay calm,' said his sister. 'You can do it.'","The whistle blew. Tom ran up a hill, but he fell behind. He was disappointed and confused about the path. Then a friend stopped to help. Tom felt grateful. He grew confident and began to run again. 'This is better than giving up,' he thought. He had been feeling worse, but now he was doing his best.","At the finish line, the other runners shouted, 'The best prize is helping!' Some hills were higher and others lower. A few runners were faster, some were slower. One boy was stronger, another was weaker. 'The worst thing would be to give up,' said the coach. Tom did not win the race. Still, he felt proud because he had finished with his friends."],"questions":["How did Tom feel at the start?","What happened on the hill?","Who helped him?","Why was Tom proud?"]}},{"id":"a1-set-31","title":"How Often? • When Things Happen • How Much?","subtitle":"A1 foundation adventure 31","level":"A1","set":31,"emoji":"🦊","color":"#F6A844","words":[{"term":"always","meaning":"دائما","example":"I always brush my teeth.","number":751,"id":"a1:751","level":"A1","lessonId":"a1-set-31"},{"term":"usually","meaning":"عادة","example":"I usually walk to school.","number":752,"id":"a1:752","level":"A1","lessonId":"a1-set-31"},{"term":"often","meaning":"غالبا","example":"We often play outside.","number":753,"id":"a1:753","level":"A1","lessonId":"a1-set-31"},{"term":"sometimes","meaning":"أحيانا","example":"I sometimes eat cake.","number":754,"id":"a1:754","level":"A1","lessonId":"a1-set-31"},{"term":"rarely","meaning":"نادرا","example":"I rarely watch TV.","number":755,"id":"a1:755","level":"A1","lessonId":"a1-set-31"},{"term":"never","meaning":"أبدا","example":"I never skip breakfast.","number":756,"id":"a1:756","level":"A1","lessonId":"a1-set-31"},{"term":"already","meaning":"بالفعل","example":"I have already finished.","number":757,"id":"a1:757","level":"A1","lessonId":"a1-set-31"},{"term":"still","meaning":"ما زال","example":"I am still reading.","number":758,"id":"a1:758","level":"A1","lessonId":"a1-set-31"},{"term":"yet","meaning":"بعد","example":"I have not eaten yet.","number":759,"id":"a1:759","level":"A1","lessonId":"a1-set-31"},{"term":"again","meaning":"مرة أخرى","example":"Please say it again.","number":760,"id":"a1:760","level":"A1","lessonId":"a1-set-31"},{"term":"early","meaning":"مبكرا","example":"We arrive early.","number":761,"id":"a1:761","level":"A1","lessonId":"a1-set-31"},{"term":"late","meaning":"متأخرا","example":"I am late today.","number":762,"id":"a1:762","level":"A1","lessonId":"a1-set-31"},{"term":"before","meaning":"قبل","example":"Wash your hands before eating.","number":763,"id":"a1:763","level":"A1","lessonId":"a1-set-31"},{"term":"after","meaning":"بعد","example":"We play after school.","number":764,"id":"a1:764","level":"A1","lessonId":"a1-set-31"},{"term":"during","meaning":"خلال","example":"Read during quiet time.","number":765,"id":"a1:765","level":"A1","lessonId":"a1-set-31"},{"term":"until","meaning":"حتى","example":"Wait until noon.","number":766,"id":"a1:766","level":"A1","lessonId":"a1-set-31"},{"term":"while","meaning":"بينما","example":"Listen while I read.","number":767,"id":"a1:767","level":"A1","lessonId":"a1-set-31"},{"term":"soon","meaning":"قريبا","example":"See you soon.","number":768,"id":"a1:768","level":"A1","lessonId":"a1-set-31"},{"term":"recently","meaning":"مؤخرا","example":"I recently visited a zoo.","number":769,"id":"a1:769","level":"A1","lessonId":"a1-set-31"},{"term":"finally","meaning":"أخيرا","example":"Finally, we finished.","number":770,"id":"a1:770","level":"A1","lessonId":"a1-set-31"},{"term":"many","meaning":"كثير من المعدود","example":"I have many books.","number":771,"id":"a1:771","level":"A1","lessonId":"a1-set-31"},{"term":"much","meaning":"كثير من غير المعدود","example":"Do not drink too much soda.","number":772,"id":"a1:772","level":"A1","lessonId":"a1-set-31"},{"term":"few","meaning":"قليل من المعدود","example":"A few birds are here.","number":773,"id":"a1:773","level":"A1","lessonId":"a1-set-31"},{"term":"several","meaning":"عدة","example":"Several children are playing.","number":774,"id":"a1:774","level":"A1","lessonId":"a1-set-31"},{"term":"enough","meaning":"كاف","example":"We have enough water.","number":775,"id":"a1:775","level":"A1","lessonId":"a1-set-31"}],"story":{"title":"The Clock That Hated Being Late","paragraphs":["A little clock called Tick always wanted to be early. It usually rang before sunrise, and it often woke the whole house. Sometimes it rang too soon; it rarely rang at the right time. It never wanted to be late. 'I have already practiced,' it said, 'but I am still not perfect yet. I will try again!'","One morning Tick was late for the school bell. 'What happened before breakfast?' asked the teacher. 'I fell asleep after the rain began,' said Tick. 'During the night, I waited until the storm stopped. While I waited, my hands became stuck. I thought the sun would rise soon. I recently had a repair, but the problem finally came back.'","The class had many ideas and much advice. A few children suggested oil. Several wanted to clean the clock. 'That is enough help!' laughed Tick. The teacher gave it a gentle tap. Its hands began moving. 'Thank you,' said Tick. 'Tomorrow I will ring at exactly the right time.'"],"questions":["What did Tick want?","Why was Tick late?","Who helped it?","What did Tick promise?"]}},{"id":"a1-set-32","title":"How Much? • Connecting Ideas • Being Polite","subtitle":"A1 foundation adventure 32","level":"A1","set":32,"emoji":"🦊","color":"#F6A844","words":[{"term":"some","meaning":"بعض","example":"I want some rice.","number":776,"id":"a1:776","level":"A1","lessonId":"a1-set-32"},{"term":"any","meaning":"أي","example":"Do you have any pencils?","number":777,"id":"a1:777","level":"A1","lessonId":"a1-set-32"},{"term":"all","meaning":"كل","example":"All the children are ready.","number":778,"id":"a1:778","level":"A1","lessonId":"a1-set-32"},{"term":"both","meaning":"كلاهما","example":"Both girls are smiling.","number":779,"id":"a1:779","level":"A1","lessonId":"a1-set-32"},{"term":"each","meaning":"كل واحد","example":"Each child has a pencil.","number":780,"id":"a1:780","level":"A1","lessonId":"a1-set-32"},{"term":"although","meaning":"على الرغم من","example":"Although it rained, we played.","number":781,"id":"a1:781","level":"A1","lessonId":"a1-set-32"},{"term":"however","meaning":"ومع ذلك","example":"It was hard; however, we tried.","number":782,"id":"a1:782","level":"A1","lessonId":"a1-set-32"},{"term":"therefore","meaning":"لذلك","example":"It rained; therefore, we stayed in.","number":783,"id":"a1:783","level":"A1","lessonId":"a1-set-32"},{"term":"instead","meaning":"بدلا من ذلك","example":"Drink water instead.","number":784,"id":"a1:784","level":"A1","lessonId":"a1-set-32"},{"term":"also","meaning":"أيضا","example":"I also like drawing.","number":785,"id":"a1:785","level":"A1","lessonId":"a1-set-32"},{"term":"besides","meaning":"بالإضافة إلى ذلك","example":"Besides English, I study math.","number":786,"id":"a1:786","level":"A1","lessonId":"a1-set-32"},{"term":"since","meaning":"منذ أو لأن","example":"I have been here since noon.","number":787,"id":"a1:787","level":"A1","lessonId":"a1-set-32"},{"term":"unless","meaning":"إلا إذا","example":"Do not go unless you ask.","number":788,"id":"a1:788","level":"A1","lessonId":"a1-set-32"},{"term":"though","meaning":"مع أن","example":"I like it, though it is hard.","number":789,"id":"a1:789","level":"A1","lessonId":"a1-set-32"},{"term":"even","meaning":"حتى","example":"Even Ali joined the game.","number":790,"id":"a1:790","level":"A1","lessonId":"a1-set-32"},{"term":"please","meaning":"من فضلك","example":"Please open the book.","number":791,"id":"a1:791","level":"A1","lessonId":"a1-set-32"},{"term":"sorry","meaning":"آسف","example":"I am sorry.","number":792,"id":"a1:792","level":"A1","lessonId":"a1-set-32"},{"term":"thanks","meaning":"شكرا","example":"Thanks for your help.","number":793,"id":"a1:793","level":"A1","lessonId":"a1-set-32"},{"term":"welcome","meaning":"أهلا","example":"Welcome to our class.","number":794,"id":"a1:794","level":"A1","lessonId":"a1-set-32"},{"term":"excuse","meaning":"يعذر","example":"Excuse me, please.","number":795,"id":"a1:795","level":"A1","lessonId":"a1-set-32"},{"term":"pardon","meaning":"عفوا","example":"Pardon me?","number":796,"id":"a1:796","level":"A1","lessonId":"a1-set-32"},{"term":"promise","meaning":"يعد","example":"I promise to help.","number":797,"id":"a1:797","level":"A1","lessonId":"a1-set-32"},{"term":"invite","meaning":"يدعو","example":"We invite our friends.","number":798,"id":"a1:798","level":"A1","lessonId":"a1-set-32"},{"term":"agree","meaning":"يوافق","example":"I agree with you.","number":799,"id":"a1:799","level":"A1","lessonId":"a1-set-32"},{"term":"refuse","meaning":"يرفض","example":"I refuse to be unkind.","number":800,"id":"a1:800","level":"A1","lessonId":"a1-set-32"}],"story":{"title":"The Invitation Mix-Up","paragraphs":["Mia wanted to invite some friends to her party. 'Do we have any paper?' she asked. 'Yes, all the cards are here,' said Leo. 'Both red and blue are nice, and each guest can choose a color.' Although Mia had a plan, the printer broke. However, she stayed calm. 'Therefore, we shall write the cards by hand instead,' she said.","'We should also make a map,' Leo added. 'Besides, the park is hard to find.' Since it was raining, they moved the party indoors. 'We can play unless the lights go out,' said Mia. Though the room was small, it felt cheerful. Even Grandpa offered to help.","At the door, Mia said, 'Please come in!' Her little brother cried, 'Sorry! I spilled the juice.' 'Thanks for telling me,' said Mia. 'You are welcome here,' she told the guests. 'Excuse me, may I pass?' asked Leo. 'Pardon?' laughed Grandpa, who had not heard. Mia made a promise to invite everyone again. The friends agree that kindness is important, and they refuse to let a little spill spoil their party."],"questions":["What happened to the printer?","Why did they move the party indoors?","What did the little brother spill?","What helped the party go well?"]}},{"id":"a1-set-33","title":"Helping Others • Clothing and Patterns • Money Matters","subtitle":"A1 foundation adventure 33","level":"A1","set":33,"emoji":"🦊","color":"#F6A844","words":[{"term":"share","meaning":"يشارك","example":"Share your crayons.","number":801,"id":"a1:801","level":"A1","lessonId":"a1-set-33"},{"term":"borrow","meaning":"يستعير","example":"May I borrow a pen?","number":802,"id":"a1:802","level":"A1","lessonId":"a1-set-33"},{"term":"lend","meaning":"يعير","example":"Can you lend me a book?","number":803,"id":"a1:803","level":"A1","lessonId":"a1-set-33"},{"term":"offer","meaning":"يعرض","example":"I offer to help.","number":804,"id":"a1:804","level":"A1","lessonId":"a1-set-33"},{"term":"receive","meaning":"يتلقى","example":"I receive a letter.","number":805,"id":"a1:805","level":"A1","lessonId":"a1-set-33"},{"term":"give","meaning":"يعطي","example":"Please give me water.","number":806,"id":"a1:806","level":"A1","lessonId":"a1-set-33"},{"term":"accept","meaning":"يقبل","example":"I accept your gift.","number":807,"id":"a1:807","level":"A1","lessonId":"a1-set-33"},{"term":"choose","meaning":"يختار","example":"Choose a color.","number":808,"id":"a1:808","level":"A1","lessonId":"a1-set-33"},{"term":"decide","meaning":"يقرر","example":"We decide together.","number":809,"id":"a1:809","level":"A1","lessonId":"a1-set-33"},{"term":"plan","meaning":"يخطط","example":"I plan my day.","number":810,"id":"a1:810","level":"A1","lessonId":"a1-set-33"},{"term":"cotton","meaning":"قطن","example":"This shirt is cotton.","number":811,"id":"a1:811","level":"A1","lessonId":"a1-set-33"},{"term":"wool","meaning":"صوف","example":"This sweater is wool.","number":812,"id":"a1:812","level":"A1","lessonId":"a1-set-33"},{"term":"silk","meaning":"حرير","example":"This scarf is silk.","number":813,"id":"a1:813","level":"A1","lessonId":"a1-set-33"},{"term":"leather","meaning":"جلد","example":"This belt is leather.","number":814,"id":"a1:814","level":"A1","lessonId":"a1-set-33"},{"term":"fabric","meaning":"قماش","example":"Feel the soft fabric.","number":815,"id":"a1:815","level":"A1","lessonId":"a1-set-33"},{"term":"pattern","meaning":"نمط","example":"I like the pattern.","number":816,"id":"a1:816","level":"A1","lessonId":"a1-set-33"},{"term":"striped","meaning":"مخطط","example":"The shirt is striped.","number":817,"id":"a1:817","level":"A1","lessonId":"a1-set-33"},{"term":"spotted","meaning":"منقط","example":"The dog is spotted.","number":818,"id":"a1:818","level":"A1","lessonId":"a1-set-33"},{"term":"plain","meaning":"سادة","example":"The dress is plain.","number":819,"id":"a1:819","level":"A1","lessonId":"a1-set-33"},{"term":"checked","meaning":"مربعات","example":"His shirt is checked.","number":820,"id":"a1:820","level":"A1","lessonId":"a1-set-33"},{"term":"bargain","meaning":"صفقة جيدة","example":"This bag is a bargain.","number":821,"id":"a1:821","level":"A1","lessonId":"a1-set-33"},{"term":"discount","meaning":"خصم","example":"We got a discount.","number":822,"id":"a1:822","level":"A1","lessonId":"a1-set-33"},{"term":"cash","meaning":"نقد","example":"I pay in cash.","number":823,"id":"a1:823","level":"A1","lessonId":"a1-set-33"},{"term":"card","meaning":"بطاقة","example":"I use my card.","number":824,"id":"a1:824","level":"A1","lessonId":"a1-set-33"},{"term":"wallet","meaning":"محفظة","example":"My wallet is small.","number":825,"id":"a1:825","level":"A1","lessonId":"a1-set-33"}],"story":{"title":"The Coat with the Kindness Pockets","paragraphs":["Lily loved to share her things. One day she asked to borrow a book. 'I can lend you mine,' said Max. He made an offer to help with her project. Lily was happy to receive the book and give him a thank-you card. 'I accept your help,' she said. 'Now we must choose a plan and decide what to make.'","They visited a costume shop. On the shelves were cotton, wool, silk, leather, and many kinds of fabric. One coat had a flower pattern; another was striped; a third was spotted. There was a plain shirt and a checked scarf. 'Let's make a coat with kindness pockets!' cried Lily. 'Each pocket can hold a good deed.'","At the counter, Max found a bargain and asked for a discount. He counted his cash, checked his bank card, and opened his wallet. The shopkeeper smiled. 'Your money is safe. And your idea is wonderful!' Together the friends made a colorful coat to remind everyone to help one another."],"questions":["What did Max lend Lily?","What did they decide to make?","Where did they choose materials?","What did the coat remind people to do?"]}},{"id":"a1-set-34","title":"Money Matters • Music and Movies • The Arts","subtitle":"A1 foundation adventure 34","level":"A1","set":34,"emoji":"🦊","color":"#F6A844","words":[{"term":"purchase","meaning":"يشتري","example":"We purchase school supplies.","number":826,"id":"a1:826","level":"A1","lessonId":"a1-set-34"},{"term":"save","meaning":"يدخر","example":"I save some money.","number":827,"id":"a1:827","level":"A1","lessonId":"a1-set-34"},{"term":"spend","meaning":"ينفق","example":"Do not spend it all.","number":828,"id":"a1:828","level":"A1","lessonId":"a1-set-34"},{"term":"refund","meaning":"استرداد المال","example":"I asked for a refund.","number":829,"id":"a1:829","level":"A1","lessonId":"a1-set-34"},{"term":"exchange","meaning":"تبديل","example":"Can I exchange this shirt?","number":830,"id":"a1:830","level":"A1","lessonId":"a1-set-34"},{"term":"movie","meaning":"فيلم","example":"The movie is funny.","number":831,"id":"a1:831","level":"A1","lessonId":"a1-set-34"},{"term":"cinema","meaning":"سينما","example":"We go to the cinema.","number":832,"id":"a1:832","level":"A1","lessonId":"a1-set-34"},{"term":"concert","meaning":"حفل موسيقي","example":"The concert begins at six.","number":833,"id":"a1:833","level":"A1","lessonId":"a1-set-34"},{"term":"museum","meaning":"متحف","example":"The museum is open.","number":834,"id":"a1:834","level":"A1","lessonId":"a1-set-34"},{"term":"theatre","meaning":"مسرح","example":"The theatre is near school.","number":835,"id":"a1:835","level":"A1","lessonId":"a1-set-34"},{"term":"music","meaning":"موسيقى","example":"I listen to music.","number":836,"id":"a1:836","level":"A1","lessonId":"a1-set-34"},{"term":"instrument","meaning":"آلة موسيقية","example":"A piano is an instrument.","number":837,"id":"a1:837","level":"A1","lessonId":"a1-set-34"},{"term":"guitar","meaning":"غيتار","example":"She plays the guitar.","number":838,"id":"a1:838","level":"A1","lessonId":"a1-set-34"},{"term":"piano","meaning":"بيانو","example":"I can play the piano.","number":839,"id":"a1:839","level":"A1","lessonId":"a1-set-34"},{"term":"drum","meaning":"طبل","example":"He beats the drum.","number":840,"id":"a1:840","level":"A1","lessonId":"a1-set-34"},{"term":"dance","meaning":"يرقص","example":"We dance to music.","number":841,"id":"a1:841","level":"A1","lessonId":"a1-set-34"},{"term":"sculpture","meaning":"منحوتة","example":"The sculpture is tall.","number":842,"id":"a1:842","level":"A1","lessonId":"a1-set-34"},{"term":"painting","meaning":"لوحة فنية","example":"The painting is beautiful.","number":843,"id":"a1:843","level":"A1","lessonId":"a1-set-34"},{"term":"drawing","meaning":"رسم","example":"My drawing is funny.","number":844,"id":"a1:844","level":"A1","lessonId":"a1-set-34"},{"term":"photography","meaning":"تصوير فوتوغرافي","example":"Photography is fun.","number":845,"id":"a1:845","level":"A1","lessonId":"a1-set-34"},{"term":"performance","meaning":"عرض","example":"The performance starts now.","number":846,"id":"a1:846","level":"A1","lessonId":"a1-set-34"},{"term":"audience","meaning":"جمهور","example":"The audience claps.","number":847,"id":"a1:847","level":"A1","lessonId":"a1-set-34"},{"term":"stage","meaning":"خشبة المسرح","example":"The actors are on stage.","number":848,"id":"a1:848","level":"A1","lessonId":"a1-set-34"},{"term":"exhibition","meaning":"معرض","example":"We visit an exhibition.","number":849,"id":"a1:849","level":"A1","lessonId":"a1-set-34"},{"term":"creative","meaning":"مبدع","example":"Maha is creative.","number":850,"id":"a1:850","level":"A1","lessonId":"a1-set-34"}],"story":{"title":"The Museum That Came Alive","paragraphs":["On Saturday, Ella wanted to purchase a ticket for a special event. She had to save her pocket money and not spend it all. The ticket seller said, 'If the show is canceled, you can ask for a refund or exchange your ticket.' Ella nodded and entered the building.","The event began with a funny movie at the cinema. Next came a concert in the old museum, followed by a play at the theatre. Music filled the rooms. A guide showed the children an instrument: a guitar, a piano, and a drum. 'Which one would you like to play?' she asked.","Suddenly a painting seemed to move! A sculpture began to dance, and a drawing on the wall waved hello. A young artist demonstrated photography. The whole performance surprised the audience. On stage, a man painted a rainbow while children explored an exhibition of creative work. 'This is the most magical museum ever!' whispered Ella. Her parents smiled. 'Art can make ordinary things feel extraordinary.'"],"questions":["What did Ella buy?","Where did the concert happen?","What strange thing happened to the art?","What did Ella learn about art?"]}},{"id":"a1-set-35","title":"Sports and Success • Sports Equipment • Geography","subtitle":"A1 foundation adventure 35","level":"A1","set":35,"emoji":"🦊","color":"#F6A844","words":[{"term":"athlete","meaning":"رياضي","example":"The athlete runs fast.","number":851,"id":"a1:851","level":"A1","lessonId":"a1-set-35"},{"term":"coach","meaning":"مدرب","example":"Our coach is kind.","number":852,"id":"a1:852","level":"A1","lessonId":"a1-set-35"},{"term":"practice","meaning":"يتدرب","example":"We practice every day.","number":853,"id":"a1:853","level":"A1","lessonId":"a1-set-35"},{"term":"competition","meaning":"مسابقة","example":"The competition is exciting.","number":854,"id":"a1:854","level":"A1","lessonId":"a1-set-35"},{"term":"race","meaning":"سباق","example":"The race starts now.","number":855,"id":"a1:855","level":"A1","lessonId":"a1-set-35"},{"term":"score","meaning":"نتيجة","example":"What is the score?","number":856,"id":"a1:856","level":"A1","lessonId":"a1-set-35"},{"term":"goal","meaning":"هدف","example":"I scored a goal.","number":857,"id":"a1:857","level":"A1","lessonId":"a1-set-35"},{"term":"win","meaning":"يفوز","example":"We hope to win.","number":858,"id":"a1:858","level":"A1","lessonId":"a1-set-35"},{"term":"lose","meaning":"يخسر","example":"It is okay to lose.","number":859,"id":"a1:859","level":"A1","lessonId":"a1-set-35"},{"term":"champion","meaning":"بطل","example":"The champion is smiling.","number":860,"id":"a1:860","level":"A1","lessonId":"a1-set-35"},{"term":"racket","meaning":"مضرب","example":"I hit the tennis ball with a racket.","number":861,"id":"a1:861","level":"A1","lessonId":"a1-set-35"},{"term":"bat","meaning":"مضرب بيسبول","example":"He swings the baseball bat carefully.","number":862,"id":"a1:862","level":"A1","lessonId":"a1-set-35"},{"term":"helmet","meaning":"خوذة","example":"Wear a helmet when you ride a bike.","number":863,"id":"a1:863","level":"A1","lessonId":"a1-set-35"},{"term":"net","meaning":"شبكة","example":"The football goes into the net.","number":864,"id":"a1:864","level":"A1","lessonId":"a1-set-35"},{"term":"whistle","meaning":"صافرة","example":"The referee blows the whistle.","number":865,"id":"a1:865","level":"A1","lessonId":"a1-set-35"},{"term":"track","meaning":"مضمار","example":"We run around the school track.","number":866,"id":"a1:866","level":"A1","lessonId":"a1-set-35"},{"term":"court","meaning":"ملعب","example":"The basketball court is behind the gym.","number":867,"id":"a1:867","level":"A1","lessonId":"a1-set-35"},{"term":"medal","meaning":"ميدالية","example":"Maha wins a medal for running.","number":868,"id":"a1:868","level":"A1","lessonId":"a1-set-35"},{"term":"trophy","meaning":"كأس","example":"The team lifts a silver trophy.","number":869,"id":"a1:869","level":"A1","lessonId":"a1-set-35"},{"term":"referee","meaning":"حكم","example":"The referee starts the game.","number":870,"id":"a1:870","level":"A1","lessonId":"a1-set-35"},{"term":"country","meaning":"بلد","example":"Italy is a country.","number":871,"id":"a1:871","level":"A1","lessonId":"a1-set-35"},{"term":"city","meaning":"مدينة","example":"London is a city.","number":872,"id":"a1:872","level":"A1","lessonId":"a1-set-35"},{"term":"town","meaning":"بلدة","example":"This town is small.","number":873,"id":"a1:873","level":"A1","lessonId":"a1-set-35"},{"term":"village","meaning":"قرية","example":"My grandparents live in a village.","number":874,"id":"a1:874","level":"A1","lessonId":"a1-set-35"},{"term":"capital","meaning":"عاصمة","example":"Paris is the capital of France.","number":875,"id":"a1:875","level":"A1","lessonId":"a1-set-35"}],"story":{"title":"The Champion’s Map","paragraphs":["At the sports center, a young athlete met her coach. 'We must practice for the big competition,' he said. 'There will be a race, a football game, and a final match. The score will matter, but helping others matters more.' The athlete hoped to score a goal and win a medal. 'What if I lose?' she asked. 'A true champion keeps trying,' he replied.","They packed a racket, a bat, a helmet, a net, and a whistle. They followed the running track past a tennis court. At the finish line were a shining trophy and a friendly referee. 'Ready?' called the coach. The athlete nodded.","Before the event, the class made a map of their country. It showed the main city, a quiet town, a small village, and the capital. The coach drew a star where the competition would take place. 'Now you know where to go,' he said. On race day, the athlete helped a fallen runner stand up. She did not finish first, but the crowd cheered as if she had won."],"questions":["Who trained the athlete?","What equipment did they pack?","What did the class make?","Why did the crowd cheer?"]}},{"id":"a1-set-36","title":"Geography • Culture Around Us • Online World","subtitle":"A1 foundation adventure 36","level":"A1","set":36,"emoji":"🦊","color":"#F6A844","words":[{"term":"continent","meaning":"قارة","example":"Asia is a continent.","number":876,"id":"a1:876","level":"A1","lessonId":"a1-set-36"},{"term":"border","meaning":"حدود","example":"We crossed the border.","number":877,"id":"a1:877","level":"A1","lessonId":"a1-set-36"},{"term":"north","meaning":"شمال","example":"North is on the map.","number":878,"id":"a1:878","level":"A1","lessonId":"a1-set-36"},{"term":"south","meaning":"جنوب","example":"We travel south.","number":879,"id":"a1:879","level":"A1","lessonId":"a1-set-36"},{"term":"east","meaning":"شرق","example":"The sun rises in the east.","number":880,"id":"a1:880","level":"A1","lessonId":"a1-set-36"},{"term":"west","meaning":"غرب","example":"The sun sets in the west.","number":881,"id":"a1:881","level":"A1","lessonId":"a1-set-36"},{"term":"national","meaning":"وطني","example":"This is our national flag.","number":882,"id":"a1:882","level":"A1","lessonId":"a1-set-36"},{"term":"international","meaning":"دولي","example":"It is an international event.","number":883,"id":"a1:883","level":"A1","lessonId":"a1-set-36"},{"term":"traditional","meaning":"تقليدي","example":"We wear traditional clothes.","number":884,"id":"a1:884","level":"A1","lessonId":"a1-set-36"},{"term":"modern","meaning":"حديث","example":"This is a modern building.","number":885,"id":"a1:885","level":"A1","lessonId":"a1-set-36"},{"term":"ancient","meaning":"قديم جدا","example":"The ancient city is old.","number":886,"id":"a1:886","level":"A1","lessonId":"a1-set-36"},{"term":"famous","meaning":"مشهور","example":"The singer is famous.","number":887,"id":"a1:887","level":"A1","lessonId":"a1-set-36"},{"term":"popular","meaning":"شائع","example":"Football is popular.","number":888,"id":"a1:888","level":"A1","lessonId":"a1-set-36"},{"term":"foreign","meaning":"أجنبي","example":"I learn a foreign language.","number":889,"id":"a1:889","level":"A1","lessonId":"a1-set-36"},{"term":"local","meaning":"محلي","example":"We buy local fruit.","number":890,"id":"a1:890","level":"A1","lessonId":"a1-set-36"},{"term":"internet","meaning":"إنترنت","example":"I use the internet to learn.","number":891,"id":"a1:891","level":"A1","lessonId":"a1-set-36"},{"term":"website","meaning":"موقع إلكتروني","example":"This website is helpful.","number":892,"id":"a1:892","level":"A1","lessonId":"a1-set-36"},{"term":"email","meaning":"بريد إلكتروني","example":"I send an email.","number":893,"id":"a1:893","level":"A1","lessonId":"a1-set-36"},{"term":"message","meaning":"رسالة","example":"Read the message.","number":894,"id":"a1:894","level":"A1","lessonId":"a1-set-36"},{"term":"online","meaning":"متصل بالإنترنت","example":"Our class meets online.","number":895,"id":"a1:895","level":"A1","lessonId":"a1-set-36"},{"term":"download","meaning":"ينزل","example":"I download a file.","number":896,"id":"a1:896","level":"A1","lessonId":"a1-set-36"},{"term":"upload","meaning":"يرفع ملفا","example":"I upload my homework.","number":897,"id":"a1:897","level":"A1","lessonId":"a1-set-36"},{"term":"password","meaning":"كلمة مرور","example":"Keep your password safe.","number":898,"id":"a1:898","level":"A1","lessonId":"a1-set-36"},{"term":"app","meaning":"تطبيق","example":"This app helps me learn.","number":899,"id":"a1:899","level":"A1","lessonId":"a1-set-36"},{"term":"digital","meaning":"رقمي","example":"This is a digital clock.","number":900,"id":"a1:900","level":"A1","lessonId":"a1-set-36"}],"story":{"title":"The Digital Postcard Mystery","paragraphs":["A digital postcard appeared on Zoe's tablet. It showed a continent, a border, and four arrows: north, south, east, and west. 'Find the hidden treasure,' the card said. 'Begin at the national museum, then visit the international festival.' Zoe opened a map on the internet.","She walked past a traditional house and a modern bridge. An ancient tower stood beside a famous statue. The festival was popular with visitors from many places. A foreign dancer taught a new song, while a local artist showed Zoe a picture of the old town.","Zoe checked the festival website and sent an email to her friend. A message came back: 'Look online for the final clue. You can download the map, but do not upload your password to any app!' Zoe laughed at the silly warning. She opened the map again and found a bright star by the river. There, beneath a tree, was a tiny treasure box. Inside was a note: 'The best adventure is learning about the world.'"],"questions":["What appeared on Zoe's tablet?","Where did the clues lead her?","What safety advice was in the message?","What was inside the treasure box?"]}}]);
